axioma_nucleo/ajuste.py:
"""Ajuste de curvas: encontrar la función que mejor describe unos datos.

A diferencia de la interpolación, la curva **no** pasa por todos los puntos: se
busca la que menos se aleja del conjunto. Es lo que se hace con datos
experimentales, que siempre traen error de medida.

Los modelos no lineales se ajustan linealizándolos (tomando logaritmos), que es
el método clásico y el que se explica en clase. Se indica cuando eso ocurre,
porque el resultado minimiza el error de la versión linealizada, no el de la
curva original.
"""

from __future__ import annotations

import math

import sympy as sp

from .estadistica import ErrorEstadistica

__all__ = [
    "ErrorAjuste",
    "Ajuste",
    "ajustar",
    "comparar",
    "MODELOS",
]

MAX_GRADO = 10


class ErrorAjuste(ErrorEstadistica):
    """Los datos no permiten ese ajuste."""


class Ajuste:
    """Resultado de un ajuste: la función, su calidad y cómo evaluarla."""

    def __init__(self, clave: str, nombre: str, expresion: sp.Expr,
                 formula: str, r2: float, linealizado: bool = False) -> None:
        self.clave = clave
        self.nombre = nombre
        self.expresion = expresion
        self.formula = formula
        self.r2 = r2
        self.linealizado = linealizado

    def evaluar(self, x: float) -> float:
        variable = sp.Symbol("x")
        try:
            return float(self.expresion.subs(variable, x))
        except (TypeError, ValueError):
            return float("nan")

    def funcion(self):
        """Versión evaluable con numpy, para dibujar la curva."""
        return sp.lambdify(sp.Symbol("x"), self.expresion, "numpy")


def _validar(x: list[float], y: list[float]) -> None:
    if len(x) != len(y):
        raise ErrorAjuste(
            f"Las dos series deben tener el mismo número de datos "
            f"(X tiene {len(x)} e Y tiene {len(y)})"
        )
    if len(x) < 3:
        raise ErrorAjuste("Hacen falta al menos 3 pares de datos para ajustar una curva")
    if len(set(x)) < 2:
        raise ErrorAjuste("Todos los valores de X son iguales: no hay nada que ajustar")


def _r2(y: list[float], predichos: list[float]) -> float:
    """Coeficiente de determinación sobre los datos **originales**.

    Se calcula siempre contra los datos sin transformar, aunque el ajuste se
    haya hecho linealizando: si no, los modelos no lineales saldrían
    artificialmente favorecidos al compararlos.
    """
    media = math.fsum(y) / len(y)
    total = math.fsum((v - media) ** 2 for v in y)
    residual = math.fsum((v - p) ** 2 for v, p in zip(y, predichos))
    if total == 0:
        return 1.0 if residual == 0 else 0.0
    return max(0.0, 1 - residual / total)


def _minimos_cuadrados(x: list[float], y: list[float], grado: int) -> list[float]:
    """Coeficientes del polinomio de mínimos cuadrados, de mayor a menor grado.

    Resuelve el sistema de ecuaciones normales con sympy para no depender de
    numpy.polyfit, y así mantener el núcleo con las mismas dependencias.
    """
    n = grado + 1
    # Sumas de potencias: Σxⁱ hasta i = 2·grado
    potencias = [math.fsum(v ** i for v in x) for i in range(2 * grado + 1)]
    momentos = [math.fsum(v ** i * w for v, w in zip(x, y)) for i in range(n)]

    matriz = sp.Matrix(n, n, lambda i, j: potencias[i + j])
    vector = sp.Matrix(n, 1, lambda i, _j: momentos[i])

    try:
        solucion = matriz.LUsolve(vector)
    except Exception:
        raise ErrorAjuste(
            f"El sistema de grado {grado} no tiene solución única con estos "
            f"datos. Pruebe con un grado menor o añada más puntos."
        ) from None

    return [float(solucion[i]) for i in range(n - 1, -1, -1)]


def _polinomico(x: list[float], y: list[float], grado: int) -> Ajuste:
    if not 1 <= grado <= MAX_GRADO:
        raise ErrorAjuste(f"El grado debe estar entre 1 y {MAX_GRADO}")
    if grado >= len(x):
        raise ErrorAjuste(
            f"Con {len(x)} puntos no se puede ajustar un polinomio de grado "
            f"{grado}: haría falta al menos {grado + 1}."
        )

    coeficientes = _minimos_cuadrados(x, y, grado)
    variable = sp.Symbol("x")
    expresion = sum(
        sp.Float(c) * variable ** (grado - i) for i, c in enumerate(coeficientes)
    )

    predichos = [float(expresion.subs(variable, v)) for v in x]
    nombre = {1: "Lineal", 2: "Cuadrático", 3: "Cúbico"}.get(grado,
                                                             f"Polinómico grado {grado}")
    return Ajuste(f"poli{grado}", nombre, expresion,
                  _formula_polinomio(coeficientes, grado), _r2(y, predichos))


def _formula_polinomio(coeficientes: list[float], grado: int) -> str:
    partes = []
    for i, c in enumerate(coeficientes):
        potencia = grado - i
        if abs(c) < 1e-14:
            continue
        if potencia == 0:
            termino = f"{c:.6g}"
        elif potencia == 1:
            termino = f"{c:.6g}·x"
        else:
            termino = f"{c:.6g}·x^{potencia}"
        partes.append(termino if not partes else
                      (f" + {termino}" if c > 0 else f" − {termino.lstrip('-')}"))
    return "y = " + ("".join(partes) or "0")


def _exponencial(x: list[float], y: list[float]) -> Ajuste:
    """y = a·e^(b·x), linealizado como ln y = ln a + b·x."""
    if any(v <= 0 for v in y):
        raise ErrorAjuste(
            "El ajuste exponencial exige que todos los valores de Y sean "
            "positivos, porque se linealiza tomando logaritmos."
        )

    logs = [math.log(v) for v in y]
    b, ln_a = _recta(x, logs)
    a = math.exp(ln_a)

    variable = sp.Symbol("x")
    expresion = sp.Float(a) * sp.exp(sp.Float(b) * variable)
    predichos = [a * math.exp(b * v) for v in x]
    return Ajuste("exponencial", "Exponencial", expresion,
                  f"y = {a:.6g}·e^({b:.6g}·x)", _r2(y, predichos), linealizado=True)


def _logaritmico(x: list[float], y: list[float]) -> Ajuste:
    """y = a + b·ln x."""
    if any(v <= 0 for v in x):
        raise ErrorAjuste(
            "El ajuste logarítmico exige que todos los valores de X sean "
            "positivos: ln(x) no existe para x ≤ 0."
        )

    logs = [math.log(v) for v in x]
    b, a = _recta(logs, y)

    variable = sp.Symbol("x")
    expresion = sp.Float(a) + sp.Float(b) * sp.log(variable)
    predichos = [a + b * math.log(v) for v in x]
    signo = "+" if b >= 0 else "−"
    return Ajuste("logaritmico", "Logarítmico", expresion,
                  f"y = {a:.6g} {signo} {abs(b):.6g}·ln(x)", _r2(y, predichos))


def _potencial(x: list[float], y: list[float]) -> Ajuste:
    """y = a·x^b, linealizado como ln y = ln a + b·ln x."""
    if any(v <= 0 for v in x) or any(v <= 0 for v in y):
        raise ErrorAjuste(
            "El ajuste potencial exige que X e Y sean positivos, porque se "
            "linealiza tomando logaritmos en los dos."
        )

    b, ln_a = _recta([math.log(v) for v in x], [math.log(v) for v in y])
    a = math.exp(ln_a)

    variable = sp.Symbol("x")
    expresion = sp.Float(a) * variable ** sp.Float(b)
    predichos = [a * v ** b for v in x]
    return Ajuste("potencial", "Potencial", expresion,
                  f"y = {a:.6g}·x^{b:.6g}", _r2(y, predichos), linealizado=True)


def _recta(x: list[float], y: list[float]) -> tuple[float, float]:
    """Pendiente y ordenada de la recta de mínimos cuadrados."""
    n = len(x)
    media_x = math.fsum(x) / n
    media_y = math.fsum(y) / n
    sxx = math.fsum((v - media_x) ** 2 for v in x)
    if sxx == 0:
        raise ErrorAjuste("Todos los valores de X son iguales")
    sxy = math.fsum((a - media_x) * (b - media_y) for a, b in zip(x, y))
    pendiente = sxy / sxx
    return pendiente, media_y - pendiente * media_x


#: (clave, título, ¿pide grado?)
MODELOS = [
    ("poli1", "Lineal   y = a·x + b", False),
    ("poli2", "Cuadrático   y = a·x² + b·x + c", False),
    ("poli3", "Cúbico", False),
    ("polinomico", "Polinómico de grado n", True),
    ("exponencial", "Exponencial   y = a·e^(b·x)", False),
    ("logaritmico", "Logarítmico   y = a + b·ln x", False),
    ("potencial", "Potencial   y = a·x^b", False),
]


def ajustar(x: list[float], y: list[float], modelo: str, grado: int = 2) -> Ajuste:
    """Ajusta un modelo concreto a los datos."""
    _validar(x, y)

    if modelo.startswith("poli") and modelo != "polinomico":
        return _polinomico(x, y, int(modelo[4:]))
    if modelo == "polinomico":
        return _polinomico(x, y, grado)
    if modelo == "exponencial":
        return _exponencial(x, y)
    if modelo == "logaritmico":
        return _logaritmico(x, y)
    if modelo == "potencial":
        return _potencial(x, y)
    raise ErrorAjuste(f"Modelo desconocido: {modelo!r}")


def comparar(x: list[float], y: list[float]) -> tuple[list[Ajuste], list[tuple[str, str]]]:
    """Prueba todos los modelos y ordena por bondad del ajuste.

    Devuelve la lista ordenada y las filas listas para mostrar, incluida la
    recomendación de cuál usar.
    """
    _validar(x, y)

    candidatos: list[Ajuste] = []
    descartados: list[tuple[str, str]] = []

    for clave in ("poli1", "poli2", "poli3", "exponencial", "logaritmico", "potencial"):
        try:
            candidatos.append(ajustar(x, y, clave))
        except ErrorAjuste as e:
            nombre = dict((c, t) for c, t, _ in MODELOS).get(clave, clave)
            descartados.append((nombre.split("   ")[0], str(e)))

    if not candidatos:
        raise ErrorAjuste("Ningún modelo se puede aplicar a estos datos")

    candidatos.sort(key=lambda a: a.r2, reverse=True)

    filas: list[tuple[str, str]] = [
        ("Número de pares", str(len(x))),
        ("", ""),
        ("Modelo", "r²  ·  ecuación"),
    ]
    for ajuste in candidatos:
        marca = "  ←  mejor" if ajuste is candidatos[0] else ""
        filas.append((ajuste.nombre, f"{ajuste.r2:.6f}  ·  {ajuste.formula}{marca}"))

    mejor = candidatos[0]
    filas.append(("", ""))
    filas.append(("Recomendado", f"{mejor.nombre}:  {mejor.formula}"))
    filas.append(("Bondad del ajuste", _interpretar_r2(mejor.r2)))

    if mejor.linealizado:
        filas.append((
            "Aviso",
            "Este modelo se ajusta linealizando (tomando logaritmos), así que "
            "minimiza el error de la versión transformada, no el de la curva "
            "original. El r² mostrado sí se calcula sobre los datos reales.",
        ))

    if descartados:
        filas.append(("", ""))
        for nombre, motivo in descartados:
            filas.append((f"{nombre}: no aplicable", motivo))

    return candidatos, filas


def _interpretar_r2(r2: float) -> str:
    if r2 >= 0.99:
        return f"{r2:.4f} — excelente: la curva explica casi toda la variación"
    if r2 >= 0.95:
        return f"{r2:.4f} — muy bueno"
    if r2 >= 0.85:
        return f"{r2:.4f} — aceptable"
    if r2 >= 0.6:
        return f"{r2:.4f} — flojo: puede que el modelo no sea el adecuado"
    return f"{r2:.4f} — malo: estos datos no siguen ese comportamiento"


def predecir(ajuste: Ajuste, valores: list[float]) -> list[tuple[str, str]]:
    """Evalúa el modelo en unos valores de x."""
    filas = [("Modelo", ajuste.formula), ("", "")]
    for x in valores:
        y = ajuste.evaluar(x)
        filas.append((f"x = {x:g}", "no definido" if math.isnan(y) else f"y = {y:.8g}"))
    return filas

axioma_nucleo/bases.py:
"""Conversión entre bases numéricas (2 a 36).

Mejoras respecto a la versión anterior, que usaba ``int(numero, base)``:

* Acepta **signo negativo** (antes ``-1010`` fallaba en la validación de dígitos).
* Acepta **parte fraccionaria** (``101.101`` en binario).
* Acepta separadores de agrupación (``_`` y espacios) y los prefijos habituales
  ``0x``, ``0b``, ``0o``.
* Da información extra útil: representación en las bases habituales, número de
  dígitos, y para los enteros el complemento a dos y el desglose posicional.
"""

from __future__ import annotations

DIGITOS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
BASE_MINIMA = 2
BASE_MAXIMA = 36

#: Precisión máxima de la parte fraccionaria, en dígitos de la base destino.
MAX_DECIMALES = 30

PREFIJOS = {"0X": 16, "0B": 2, "0O": 8, "0D": 10}

NOMBRES_BASE = {
    2: "binario", 8: "octal", 10: "decimal", 16: "hexadecimal",
    3: "ternario", 4: "cuaternario", 5: "quinario", 12: "duodecimal",
    20: "vigesimal", 32: "base 32", 36: "base 36",
}


class ErrorBase(ValueError):
    """El número o la base indicados no son válidos."""


def nombre_base(base: int) -> str:
    nombre = NOMBRES_BASE.get(base)
    return f"base {base} ({nombre})" if nombre else f"base {base}"


def _validar_base(base: int, etiqueta: str) -> int:
    if not isinstance(base, int) or not (BASE_MINIMA <= base <= BASE_MAXIMA):
        raise ErrorBase(f"La {etiqueta} debe estar entre {BASE_MINIMA} y {BASE_MAXIMA}")
    return base


def limpiar(texto: str, base: int) -> tuple[int, str, str]:
    """Normaliza la entrada y la separa en (signo, parte entera, parte fraccionaria).

    Devuelve los dígitos en mayúsculas, sin separadores ni prefijo.
    """
    limpio = texto.strip().upper().replace("_", "").replace(" ", "")
    if not limpio:
        raise ErrorBase("Introduzca un número")

    signo = 1
    if limpio[0] in "+-":
        signo = -1 if limpio[0] == "-" else 1
        limpio = limpio[1:]

    # Prefijos: sólo se aceptan si coinciden con la base indicada.
    if len(limpio) > 2 and limpio[:2] in PREFIJOS:
        if PREFIJOS[limpio[:2]] != base:
            raise ErrorBase(
                f"El prefijo «{limpio[:2].lower()}» corresponde a "
                f"base {PREFIJOS[limpio[:2]]}, no a base {base}"
            )
        limpio = limpio[2:]

    limpio = limpio.replace(",", ".")
    if limpio.count(".") > 1:
        raise ErrorBase("El número tiene más de un separador decimal")

    entera, _, fraccionaria = limpio.partition(".")
    if not entera and not fraccionaria:
        raise ErrorBase("Introduzca un número")

    validos = DIGITOS[:base]
    for parte in (entera, fraccionaria):
        for digito in parte:
            if digito not in validos:
                permitidos = validos if base <= 16 else f"0-9 y A-{validos[-1]}"
                raise ErrorBase(
                    f"El dígito «{digito}» no existe en {nombre_base(base)}. "
                    f"Dígitos permitidos: {permitidos}"
                )

    return signo, entera or "0", fraccionaria


def a_decimal(texto: str, base: int) -> float | int:
    """Convierte ``texto`` (en ``base``) a un número decimal de Python.

    Devuelve ``int`` si no hay parte fraccionaria, para no perder precisión con
    números grandes.
    """
    _validar_base(base, "base de origen")
    signo, entera, fraccionaria = limpiar(texto, base)

    valor_entero = int(entera, base) if entera else 0
    if not fraccionaria:
        return signo * valor_entero

    valor_frac = 0.0
    for posicion, digito in enumerate(fraccionaria, start=1):
        valor_frac += DIGITOS.index(digito) / (base ** posicion)
    return signo * (valor_entero + valor_frac)


def desde_decimal(valor: float | int, base: int, decimales: int = 12) -> str:
    """Representa ``valor`` (decimal) en ``base``."""
    _validar_base(base, "base de destino")
    decimales = max(0, min(MAX_DECIMALES, int(decimales)))

    negativo = valor < 0
    valor = abs(valor)

    if isinstance(valor, int):
        entero, fraccion = valor, 0.0
    else:
        entero = int(valor)
        fraccion = valor - entero

    texto = _entero_a_base(entero, base)

    if fraccion > 0 and decimales > 0:
        digitos = []
        resto = fraccion
        for _ in range(decimales):
            resto *= base
            digito = int(resto)
            digitos.append(DIGITOS[digito])
            resto -= digito
            if resto <= 0:
                break
        # Redondeo del último dígito si queda resto significativo.
        if resto >= 0.5 and digitos:
            digitos = _redondear_fraccion(digitos, base)
        texto += "." + "".join(digitos).rstrip("0")
        texto = texto.rstrip(".")

    return ("-" if negativo else "") + texto


def _entero_a_base(entero: int, base: int) -> str:
    if entero == 0:
        return "0"
    digitos: list[str] = []
    while entero > 0:
        entero, resto = divmod(entero, base)
        digitos.append(DIGITOS[resto])
    return "".join(reversed(digitos))


def _redondear_fraccion(digitos: list[str], base: int) -> list[str]:
    """Suma 1 al último dígito propagando el acarreo."""
    resultado = list(digitos)
    i = len(resultado) - 1
    while i >= 0:
        indice = DIGITOS.index(resultado[i]) + 1
        if indice < base:
            resultado[i] = DIGITOS[indice]
            return resultado
        resultado[i] = "0"
        i -= 1
    return resultado


def convertir(texto: str, base_origen: int, base_destino: int, decimales: int = 12) -> str:
    """Convierte ``texto`` de ``base_origen`` a ``base_destino``."""
    _validar_base(base_origen, "base de origen")
    _validar_base(base_destino, "base de destino")
    return desde_decimal(a_decimal(texto, base_origen), base_destino, decimales)


def tabla_bases(texto: str, base_origen: int, decimales: int = 12) -> list[tuple[int, str]]:
    """Representación del número en las bases de uso habitual."""
    valor = a_decimal(texto, base_origen)
    return [(base, desde_decimal(valor, base, decimales)) for base in (2, 8, 10, 16)]


def desglose_posicional(texto: str, base: int, max_terminos: int = 24) -> str:
    """Explica el valor como suma de potencias, p. ej. ``1·2³ + 0·2² + 1·2¹``."""
    signo, entera, fraccionaria = limpiar(texto, base)
    terminos: list[str] = []

    for i, digito in enumerate(entera):
        exponente = len(entera) - 1 - i
        terminos.append(f"{DIGITOS.index(digito)}·{base}^{exponente}")
    for i, digito in enumerate(fraccionaria, start=1):
        terminos.append(f"{DIGITOS.index(digito)}·{base}^-{i}")

    if len(terminos) > max_terminos:
        terminos = terminos[:max_terminos] + ["…"]

    prefijo = "-(" if signo < 0 else ""
    sufijo = ")" if signo < 0 else ""
    return prefijo + " + ".join(terminos) + sufijo


#: Operaciones bit a bit disponibles. El segundo operando de NOT se ignora.
OPERACIONES_BITS = ["AND", "OR", "XOR", "NOT", "<<", ">>"]

#: Anchos de palabra para mostrar el resultado en binario.
ANCHOS = (8, 16, 32, 64)

MAX_DESPLAZAMIENTO = 512


def operacion_bits(operacion: str, a: int, b: int = 0,
                   ancho: int | None = None) -> list[tuple[str, str]]:
    """Aplica una operación bit a bit y muestra el resultado en varias bases.

    ``ancho`` fija los bits de la palabra; si es ``None`` se elige el menor de
    8/16/32/64 que quepa. Con NOT hace falta un ancho, porque ``~x`` sobre
    enteros de precisión arbitraria daría infinitos unos a la izquierda.
    """
    if operacion not in OPERACIONES_BITS:
        raise ErrorBase(f"Operación desconocida: {operacion!r}")
    if a < 0 or b < 0:
        raise ErrorBase("Las operaciones bit a bit sólo admiten enteros no negativos")

    if ancho is None:
        necesarios = max(a.bit_length(), b.bit_length() if operacion in ("AND", "OR", "XOR") else 0, 1)
        if operacion == "<<":
            necesarios += b
        ancho = next((w for w in ANCHOS if necesarios <= w), None)
        if ancho is None:
            raise ErrorBase("Los operandos no caben en una palabra de 64 bits")

    mascara = (1 << ancho) - 1

    if operacion in ("<<", ">>"):
        if b > MAX_DESPLAZAMIENTO:
            raise ErrorBase(f"El desplazamiento máximo es {MAX_DESPLAZAMIENTO}")
        resultado = (a << b) & mascara if operacion == "<<" else (a >> b)
    elif operacion == "AND":
        resultado = a & b
    elif operacion == "OR":
        resultado = a | b
    elif operacion == "XOR":
        resultado = a ^ b
    else:  # NOT
        resultado = (~a) & mascara

    def binario(valor: int) -> str:
        return _agrupar_bits(format(valor & mascara, f"0{ancho}b"))

    filas: list[tuple[str, str]] = [("Palabra", f"{ancho} bits")]

    if operacion == "NOT":
        filas.append(("A  (binario)", binario(a)))
        filas.append(("NOT A", binario(resultado)))
    elif operacion in ("<<", ">>"):
        filas.append(("A  (binario)", binario(a)))
        filas.append((f"A {operacion} {b}", binario(resultado)))
    else:
        filas.append(("A  (binario)", binario(a)))
        filas.append(("B  (binario)", binario(b)))
        filas.append((f"A {operacion} B", binario(resultado)))

    filas.append(("", ""))
    filas.append(("Resultado (decimal)", str(resultado)))
    filas.append(("Resultado (hexadecimal)", format(resultado & mascara, f"0{max(1, ancho // 4)}X")))
    filas.append(("Resultado (octal)", _entero_a_base(resultado, 8)))
    filas.append(("Bits a 1", str(bin(resultado & mascara).count("1"))))
    return filas


def _agrupar_bits(binario: str, tamano: int = 4) -> str:
    """Agrupa los bits de cuatro en cuatro para poder leerlos."""
    resto = len(binario) % tamano
    grupos = ([binario[:resto]] if resto else []) + [
        binario[i:i + tamano] for i in range(resto, len(binario), tamano)
    ]
    return " ".join(g for g in grupos if g)


def info_entero(valor: int) -> list[tuple[str, str]]:
    """Datos de interés para un entero: bits necesarios, complemento a dos, etc."""
    datos: list[tuple[str, str]] = []
    magnitud = abs(valor)
    necesarios = magnitud.bit_length() or 1
    datos.append(("Bits necesarios (magnitud)", str(necesarios)))

    if valor >= 0:
        datos.append(("Binario", _entero_a_base(magnitud, 2)))
    else:
        datos.append(("Binario (magnitud)", _entero_a_base(magnitud, 2)))

    for ancho in (8, 16, 32, 64):
        if necesarios + (1 if valor < 0 else 0) <= ancho:
            complemento = valor & ((1 << ancho) - 1)
            datos.append((
                f"Complemento a dos ({ancho} bits)",
                format(complemento, f"0{ancho}b"),
            ))
            datos.append((f"Hexadecimal ({ancho} bits)", format(complemento, f"0{ancho // 4}X")))
            break
    else:
        datos.append(("Complemento a dos", "el número excede los 64 bits"))

    if valor >= 0:
        datos.append(("Bits a 1 (población)", str(bin(magnitud).count("1"))))
    return datos

axioma_nucleo/calculo.py:
"""Cálculo simbólico: derivadas, integrales, límites y series.

Todo devuelve pares (etiqueta, valor) para que el panel sólo tenga que
mostrarlos, y todo error sale como ``ErrorSimbolico`` con un mensaje en
castellano.
"""

from __future__ import annotations

import sympy as sp

from .simbolico import ErrorSimbolico, analizar, incognitas, texto, variable_principal

__all__ = [
    "derivar",
    "integrar",
    "integrar_definida",
    "limite",
    "serie_taylor",
    "analizar_funcion",
    "puntos_criticos",
    "OPERACIONES",
]

#: Límite de seguridad: sympy puede tardar mucho con expresiones patológicas.
_ORDEN_MAXIMO = 10


def _preparar(expresion_texto: str, variable_texto: str = "") -> tuple[sp.Expr, sp.Symbol]:
    expresion = analizar(expresion_texto)
    variable = variable_principal(expresion, variable_texto.strip())
    return expresion, variable


def derivar(expresion_texto: str, variable_texto: str = "", orden: int = 1) -> list[tuple[str, str]]:
    """Derivada de orden ``orden`` respecto a ``variable_texto``."""
    if not 1 <= orden <= _ORDEN_MAXIMO:
        raise ErrorSimbolico(f"El orden debe estar entre 1 y {_ORDEN_MAXIMO}")

    expresion, variable = _preparar(expresion_texto, variable_texto)
    try:
        derivada = sp.diff(expresion, variable, orden)
    except (ValueError, TypeError, NotImplementedError) as e:
        raise ErrorSimbolico(f"No se pudo derivar: {e}") from e

    filas = [
        ("Función", f"f({variable}) = {texto(expresion)}"),
        (f"Derivada de orden {orden}", texto(sp.simplify(derivada))),
    ]

    sin_simplificar = texto(derivada)
    if sin_simplificar != texto(sp.simplify(derivada)):
        filas.append(("Sin simplificar", sin_simplificar))

    factorizada = sp.factor(derivada)
    if texto(factorizada) != texto(sp.simplify(derivada)):
        filas.append(("Factorizada", texto(factorizada)))

    # Las derivadas intermedias ayudan a seguir el proceso.
    if orden > 1:
        parcial = expresion
        for k in range(1, orden):
            parcial = sp.diff(parcial, variable)
            filas.append((f"  · derivada {k}ª", texto(sp.simplify(parcial))))

    return filas


def integrar(expresion_texto: str, variable_texto: str = "") -> list[tuple[str, str]]:
    """Integral indefinida."""
    expresion, variable = _preparar(expresion_texto, variable_texto)
    try:
        primitiva = sp.integrate(expresion, variable)
    except (ValueError, TypeError, NotImplementedError) as e:
        raise ErrorSimbolico(f"No se pudo integrar: {e}") from e

    if primitiva.has(sp.Integral):
        raise ErrorSimbolico(
            "Esta integral no tiene primitiva expresable con funciones elementales. "
            "Pruebe con la integral definida, que se calcula numéricamente."
        )

    filas = [
        ("Función", f"f({variable}) = {texto(expresion)}"),
        ("Integral indefinida", f"{texto(sp.simplify(primitiva))} + C"),
    ]
    comprobacion = sp.simplify(sp.diff(primitiva, variable) - expresion)
    filas.append((
        "Comprobación (derivar el resultado)",
        "correcto: se recupera f" if comprobacion == 0 else texto(comprobacion),
    ))
    return filas


def integrar_definida(expresion_texto: str, variable_texto: str,
                      inferior: str, superior: str) -> list[tuple[str, str]]:
    """Integral definida entre dos límites, con valor exacto y aproximado."""
    expresion, variable = _preparar(expresion_texto, variable_texto)
    a = analizar(inferior)
    b = analizar(superior)

    try:
        valor = sp.integrate(expresion, (variable, a, b))
    except (ValueError, TypeError, NotImplementedError) as e:
        raise ErrorSimbolico(f"No se pudo integrar: {e}") from e

    filas = [
        ("Función", f"f({variable}) = {texto(expresion)}"),
        ("Intervalo", f"de {texto(a)} a {texto(b)}"),
    ]

    if valor.has(sp.Integral) or valor.has(sp.nan):
        # Sin primitiva elemental: se recurre a la cuadratura numérica.
        try:
            aproximado = sp.N(sp.Integral(expresion, (variable, a, b)).evalf())
        except (ValueError, TypeError) as e:
            raise ErrorSimbolico(f"La integral no converge o no se puede calcular: {e}") from e
        filas.append(("Valor (numérico)", texto(aproximado)))
        filas.append(("Nota", "sin primitiva elemental: calculada por cuadratura numérica"))
        return filas

    filas.append(("Valor exacto", texto(sp.simplify(valor))))
    try:
        filas.append(("Valor aproximado", texto(sp.N(valor, 10))))
    except (TypeError, ValueError):
        pass

    if valor.is_real is not False:
        filas.append((
            "Interpretación",
            "área con signo entre la curva y el eje horizontal",
        ))
    return filas


def limite(expresion_texto: str, variable_texto: str, punto: str,
           direccion: str = "ambos") -> list[tuple[str, str]]:
    """Límite en un punto. ``direccion`` es ``"ambos"``, ``"+"`` o ``"-"``."""
    expresion, variable = _preparar(expresion_texto, variable_texto)
    destino = analizar(punto) if punto.strip() not in ("oo", "+oo", "inf") else sp.oo
    if punto.strip() in ("-oo", "-inf"):
        destino = -sp.oo

    filas = [
        ("Función", f"f({variable}) = {texto(expresion)}"),
        ("Punto", texto(destino)),
    ]

    def calcular(lado: str):
        try:
            return sp.limit(expresion, variable, destino, lado)
        except (ValueError, TypeError, NotImplementedError) as e:
            raise ErrorSimbolico(f"No se pudo calcular el límite: {e}") from e

    if direccion == "+":
        filas.append(("Límite por la derecha", texto(calcular("+"))))
    elif direccion == "-":
        filas.append(("Límite por la izquierda", texto(calcular("-"))))
    else:
        por_izquierda = calcular("-")
        por_derecha = calcular("+")
        filas.append(("Límite por la izquierda", texto(por_izquierda)))
        filas.append(("Límite por la derecha", texto(por_derecha)))
        if sp.simplify(por_izquierda - por_derecha) == 0:
            filas.append(("Límite", texto(por_derecha)))
        else:
            filas.append(("Límite", "no existe: los límites laterales no coinciden"))
    return filas


def serie_taylor(expresion_texto: str, variable_texto: str, punto: str = "0",
                 orden: int = 5) -> list[tuple[str, str]]:
    """Desarrollo en serie de Taylor (de Maclaurin si el punto es 0)."""
    if not 1 <= orden <= 20:
        raise ErrorSimbolico("El orden debe estar entre 1 y 20")

    expresion, variable = _preparar(expresion_texto, variable_texto)
    centro = analizar(punto) if punto.strip() else sp.Integer(0)

    try:
        serie = sp.series(expresion, variable, centro, orden + 1)
    except (ValueError, TypeError, NotImplementedError) as e:
        raise ErrorSimbolico(f"No se pudo desarrollar la serie: {e}") from e

    polinomio = serie.removeO()
    nombre = "Maclaurin" if centro == 0 else "Taylor"
    return [
        ("Función", f"f({variable}) = {texto(expresion)}"),
        ("Centro del desarrollo", texto(centro)),
        (f"Serie de {nombre} (orden {orden})", texto(serie)),
        ("Polinomio (sin el resto)", texto(sp.expand(polinomio))),
    ]


def puntos_criticos(expresion_texto: str, variable_texto: str = "") -> list[tuple[str, str]]:
    """Máximos, mínimos, inflexiones y asíntotas de una función de una variable."""
    expresion, variable = _preparar(expresion_texto, variable_texto)

    primera = sp.diff(expresion, variable)
    segunda = sp.diff(primera, variable)

    filas = [
        ("Función", f"f({variable}) = {texto(expresion)}"),
        ("f'", texto(sp.simplify(primera))),
        ("f''", texto(sp.simplify(segunda))),
    ]

    try:
        criticos = sp.solve(sp.Eq(primera, 0), variable)
    except (ValueError, TypeError, NotImplementedError):
        criticos = []

    if not criticos:
        filas.append(("Puntos críticos", "no se encontraron (o no son resolubles)"))
    else:
        for punto in criticos:
            if punto.free_symbols:
                continue
            try:
                curvatura = sp.N(segunda.subs(variable, punto))
                altura = sp.N(expresion.subs(variable, punto), 8)
            except (TypeError, ValueError):
                continue
            if not curvatura.is_real:
                continue
            if curvatura > 0:
                tipo = "mínimo local"
            elif curvatura < 0:
                tipo = "máximo local"
            else:
                tipo = "posible inflexión (f'' = 0)"
            filas.append((f"{variable} = {texto(sp.N(punto, 8))}", f"{tipo}, f = {texto(altura)}"))

    try:
        inflexiones = [p for p in sp.solve(sp.Eq(segunda, 0), variable) if not p.free_symbols]
        if inflexiones:
            filas.append((
                "Puntos de inflexión",
                ", ".join(f"{variable} = {texto(sp.N(p, 8))}" for p in inflexiones[:8]),
            ))
    except (ValueError, TypeError, NotImplementedError):
        pass

    for etiqueta, destino in (("Límite en +∞", sp.oo), ("Límite en −∞", -sp.oo)):
        try:
            filas.append((etiqueta, texto(sp.limit(expresion, variable, destino))))
        except (ValueError, TypeError, NotImplementedError):
            pass

    return filas


def analizar_funcion(expresion_texto: str, variable_texto: str = "") -> list[tuple[str, str]]:
    """Ficha completa: dominio, cortes con los ejes, paridad y periodicidad."""
    expresion, variable = _preparar(expresion_texto, variable_texto)
    filas: list[tuple[str, str]] = [("Función", f"f({variable}) = {texto(expresion)}")]

    if len(incognitas(expresion)) > 1:
        filas.append(("Aviso", "la función tiene más de una variable; se analiza respecto a "
                               f"«{variable}»"))

    try:
        dominio = sp.calculus.util.continuous_domain(expresion, variable, sp.S.Reals)
        filas.append(("Dominio", texto(dominio)))
    except (ValueError, TypeError, NotImplementedError):
        filas.append(("Dominio", "no se pudo determinar"))

    try:
        recorrido = sp.calculus.util.function_range(expresion, variable, sp.S.Reals)
        filas.append(("Recorrido", texto(recorrido)))
    except (ValueError, TypeError, NotImplementedError):
        pass

    try:
        filas.append(("Corte con el eje Y", texto(sp.simplify(expresion.subs(variable, 0)))))
    except (TypeError, ValueError, ZeroDivisionError):
        filas.append(("Corte con el eje Y", "no existe (no está definida en 0)"))

    try:
        raices = [r for r in sp.solve(sp.Eq(expresion, 0), variable) if not r.free_symbols]
        reales = [r for r in raices if sp.im(sp.N(r)) == 0]
        filas.append((
            "Cortes con el eje X",
            ", ".join(f"{variable} = {texto(sp.N(r, 8))}" for r in reales[:10]) or "ninguno real",
        ))
    except (ValueError, TypeError, NotImplementedError):
        filas.append(("Cortes con el eje X", "no se pudieron calcular"))

    par = sp.simplify(expresion.subs(variable, -variable) - expresion) == 0
    impar = sp.simplify(expresion.subs(variable, -variable) + expresion) == 0
    filas.append(("Simetría", "par (respecto al eje Y)" if par
                  else "impar (respecto al origen)" if impar else "ninguna"))

    try:
        periodo = sp.periodicity(expresion, variable)
        if periodo:
            filas.append(("Periodo", texto(periodo)))
    except (ValueError, TypeError, NotImplementedError):
        pass

    return filas


#: (clave, título, campos que necesita) — lo consume el panel para montar el formulario.
OPERACIONES = [
    ("derivada", "Derivada", ["expresion", "variable", "orden"]),
    ("integral", "Integral indefinida", ["expresion", "variable"]),
    ("integral_definida", "Integral definida", ["expresion", "variable", "desde", "hasta"]),
    ("limite", "Límite", ["expresion", "variable", "punto", "direccion"]),
    ("taylor", "Serie de Taylor", ["expresion", "variable", "punto", "orden"]),
    ("criticos", "Máximos, mínimos e inflexiones", ["expresion", "variable"]),
    ("analisis", "Análisis completo de la función", ["expresion", "variable"]),
]

axioma_nucleo/config.py:
"""Preferencias persistentes de la aplicación."""

from __future__ import annotations

import json
import logging
from typing import Any

from .rutas import archivo_datos

log = logging.getLogger(__name__)

ARCHIVO = "config.json"

PREDETERMINADOS: dict[str, Any] = {
    "tema": "oscuro",            # "oscuro" | "claro"
    "modo_angulo": "DEG",        # "DEG" | "RAD" | "GRAD"
    "decimales": 6,              # dígitos significativos al mostrar resultados
    "max_historial": 500,        # entradas guardadas por módulo
    "modulo_inicial": "calculadora",
    "ventana": {},               # geometría de la ventana principal
    "disposicion": {},           # apartados abiertos y dónde estaba cada uno
    "max_paneles": 0,            # apartados a la vez; 0 = sin tope
}


class Config:
    """Diccionario de preferencias con carga y guardado en disco."""

    def __init__(self) -> None:
        self._datos: dict[str, Any] = dict(PREDETERMINADOS)
        self.cargar()

    def cargar(self) -> None:
        ruta = archivo_datos(ARCHIVO)
        if not ruta.exists():
            return
        try:
            with ruta.open(encoding="utf-8") as f:
                guardado = json.load(f)
            if isinstance(guardado, dict):
                # Sólo aceptamos claves conocidas para que un archivo viejo o
                # corrupto no introduzca basura en la configuración.
                for clave in PREDETERMINADOS:
                    if clave in guardado:
                        self._datos[clave] = guardado[clave]
        except (OSError, ValueError) as e:
            log.warning("No se pudo leer la configuración: %s", e)

    def guardar(self) -> None:
        ruta = archivo_datos(ARCHIVO)
        try:
            temporal = ruta.with_suffix(".tmp")
            with temporal.open("w", encoding="utf-8") as f:
                json.dump(self._datos, f, indent=2, ensure_ascii=False)
            temporal.replace(ruta)
        except OSError as e:
            log.warning("No se pudo guardar la configuración: %s", e)

    def get(self, clave: str, defecto: Any = None) -> Any:
        return self._datos.get(clave, defecto if defecto is not None else PREDETERMINADOS.get(clave))

    def set(self, clave: str, valor: Any) -> None:
        self._datos[clave] = valor

    def __getitem__(self, clave: str) -> Any:
        return self.get(clave)

    def __setitem__(self, clave: str, valor: Any) -> None:
        self.set(clave, valor)


# Instancia compartida por toda la aplicación.
config = Config()

axioma_nucleo/evaluador.py:
"""Evaluador de expresiones matemáticas.

La versión anterior usaba ``eval()`` sobre el texto que escribía el usuario. Eso
significa que cualquier expresión pegada en la pantalla podía ejecutar código
arbitrario (``__import__('os').system(...)``) y que un simple ``1/0`` mostraba un
mensaje de error de Python en lugar de algo comprensible.

Aquí la expresión se **compila a un árbol de sintaxis** (``ast``) y se recorre
permitiendo únicamente números, operadores aritméticos y una lista blanca de
funciones y constantes. No hay acceso a atributos, nombres, llamadas dinámicas
ni comprensiones, así que no hay forma de salir del sandbox.
"""

from __future__ import annotations

import ast
import math
import operator
import re

__all__ = ["ErrorExpresion", "evaluar", "FUNCIONES", "CONSTANTES", "MODOS_ANGULO"]

MODOS_ANGULO = ("DEG", "RAD", "GRAD")

# Límite para el factorial: 10000! ya tiene 35 660 dígitos y calcularlo dentro de
# una expresión más grande puede congelar la interfaz.
_MAX_FACTORIAL = 10_000


class ErrorExpresion(ValueError):
    """La expresión no es válida o no se puede evaluar."""


# --------------------------------------------------------------------------- #
# Preprocesado del texto
# --------------------------------------------------------------------------- #

_SUSTITUCIONES = {
    "×": "*", "·": "*", "✕": "*", "∗": "*",
    "÷": "/", "∕": "/", "：": "/",
    "−": "-", "–": "-", "—": "-",
    "π": "pi", "τ": "tau", "φ": "phi", "∞": "inf",
    "²": "**2", "³": "**3", "⁴": "**4",
    "≤": "<=", "≥": ">=",
    "^": "**",
}

# Multiplicación implícita: sólo en los casos donde no hay ambigüedad posible.
# Deliberadamente NO se inserta entre dígito y letra, para no romper la notación
# científica (`1e5`) ni nombres de función con cifras (`log10`).
_IMPLICITA = (
    # `2(3+4)`, `2π`, `3√2`. El lookbehind exige que la cifra empiece un token
    # nuevo, para no partir nombres como `log10` o `log2`.
    (re.compile(r"(?<![\w.])(\d+(?:\.\d+)?)\s*(?=[π√∛(])"), r"\1*"),
    # `π2`, `π(...)`, `ππ`.
    (re.compile(r"(π)\s*(?=[\w(π√∛])"), r"\1*"),
    # `(1+2)(3+4)`, `(1+2)3`, `(1+2)x`.
    (re.compile(r"(\))\s*(?=[\w(π√∛])"), r"\1*"),
)

_PORCENTAJE = re.compile(r"(\d+(?:\.\d+)?)\s*%")

# Los símbolos de raíz son prefijos, no nombres: `√9` debe volverse `sqrt(9)` y no
# `sqrt9`, que sería un nombre desconocido.
_PREFIJOS_RAIZ = (("√", "sqrt"), ("∛", "cbrt"))
_OPERANDO_SIMPLE = r"(\d+(?:\.\d+)?|[A-Za-z_]\w*)"


def _preparar(expresion: str) -> str:
    """Normaliza la notación «de calculadora» a sintaxis de Python."""
    texto = expresion.strip()
    if not texto:
        raise ErrorExpresion("Ingrese una expresión")

    for patron, reemplazo in _IMPLICITA:
        texto = patron.sub(reemplazo, texto)

    # `50%` significa 0.5, como en cualquier calculadora. Para el resto (módulo)
    # existe la función `mod(a, b)`.
    texto = _PORCENTAJE.sub(r"(\1/100)", texto)

    for simbolo, funcion in _PREFIJOS_RAIZ:
        texto = re.sub(f"{simbolo}\\s*{_OPERANDO_SIMPLE}", rf"{funcion}(\1)", texto)
        texto = texto.replace(simbolo, funcion)  # queda el caso `√(...)`

    for simbolo, reemplazo in _SUSTITUCIONES.items():
        texto = texto.replace(simbolo, reemplazo)

    texto = _expandir_factoriales(texto)
    return texto


def _expandir_factoriales(texto: str) -> str:
    """Convierte el ``!`` postfijo en llamadas a ``factorial(...)``.

    Recorre el texto de izquierda a derecha; al encontrar un ``!`` busca hacia
    atrás el operando completo (un número, un nombre o un paréntesis
    equilibrado) y lo envuelve.
    """
    resultado = texto
    while True:
        pos = resultado.find("!")
        if pos == -1:
            return resultado
        # `!=` es una comparación, no un factorial.
        if resultado[pos + 1 : pos + 2] == "=":
            siguiente = resultado.find("!", pos + 1)
            if siguiente == -1:
                return resultado
            pos = siguiente

        inicio = _inicio_operando(resultado, pos)
        if inicio is None:
            raise ErrorExpresion("El signo '!' debe ir después de un número")
        operando = resultado[inicio:pos]
        resultado = f"{resultado[:inicio]}factorial({operando}){resultado[pos + 1:]}"


def _inicio_operando(texto: str, fin: int) -> int | None:
    """Índice donde empieza el operando que termina justo antes de ``fin``."""
    i = fin - 1
    while i >= 0 and texto[i].isspace():
        i -= 1
    if i < 0:
        return None

    if texto[i] == ")":
        profundidad = 0
        while i >= 0:
            if texto[i] == ")":
                profundidad += 1
            elif texto[i] == "(":
                profundidad -= 1
                if profundidad == 0:
                    # Incluye el nombre de la función si la hay: `sin(x)!`
                    j = i - 1
                    while j >= 0 and (texto[j].isalnum() or texto[j] == "_"):
                        j -= 1
                    return j + 1
            i -= 1
        return None

    if texto[i].isalnum() or texto[i] in "._":
        while i >= 0 and (texto[i].isalnum() or texto[i] in "._"):
            i -= 1
        return i + 1
    return None


# --------------------------------------------------------------------------- #
# Funciones y constantes permitidas
# --------------------------------------------------------------------------- #


def _factorial(x):
    if isinstance(x, float):
        if not x.is_integer():
            # Para no enteros el factorial se extiende con la función gamma.
            return math.gamma(x + 1)
        x = int(x)
    if x < 0:
        raise ErrorExpresion("El factorial requiere un número no negativo")
    if x > _MAX_FACTORIAL:
        raise ErrorExpresion(f"Factorial demasiado grande (máximo {_MAX_FACTORIAL})")
    return math.factorial(x)


def _raiz(x):
    if x < 0:
        raise ErrorExpresion("La raíz cuadrada de un número negativo no es real")
    return math.sqrt(x)


def _raiz_n(x, n):
    if n == 0:
        raise ErrorExpresion("El índice de la raíz no puede ser 0")
    if x < 0:
        if int(n) == n and int(n) % 2 == 1:
            return -((-x) ** (1.0 / n))
        raise ErrorExpresion("Raíz de índice par de un número negativo")
    return x ** (1.0 / n)


def _log(x, base=None):
    if x <= 0:
        raise ErrorExpresion("El logaritmo requiere un número positivo")
    if base is None:
        return math.log(x)
    if base <= 0 or base == 1:
        raise ErrorExpresion("Base de logaritmo inválida")
    return math.log(x, base)


def _asegurar_dominio(nombre: str, x, minimo: float, maximo: float):
    if not (minimo <= x <= maximo):
        raise ErrorExpresion(f"{nombre} sólo acepta valores entre {minimo} y {maximo}")
    return x


class _Trig:
    """Envuelve las funciones trigonométricas aplicando el modo de ángulo."""

    def __init__(self, modo: str = "RAD") -> None:
        self.modo = modo if modo in MODOS_ANGULO else "RAD"

    def a_radianes(self, valor: float) -> float:
        if self.modo == "DEG":
            return math.radians(valor)
        if self.modo == "GRAD":
            return valor * math.pi / 200.0
        return valor

    def desde_radianes(self, valor: float) -> float:
        if self.modo == "DEG":
            return math.degrees(valor)
        if self.modo == "GRAD":
            return valor * 200.0 / math.pi
        return valor

    def funciones(self) -> dict:
        r, d = self.a_radianes, self.desde_radianes
        return {
            "sin": lambda x: _redondear_ruido(math.sin(r(x))),
            "cos": lambda x: _redondear_ruido(math.cos(r(x))),
            "tan": lambda x: _tan(r(x)),
            "sec": lambda x: _dividir(1.0, math.cos(r(x)), "sec"),
            "csc": lambda x: _dividir(1.0, math.sin(r(x)), "csc"),
            "cot": lambda x: _dividir(1.0, _tan(r(x)), "cot"),
            "asin": lambda x: d(math.asin(_asegurar_dominio("asin", x, -1, 1))),
            "acos": lambda x: d(math.acos(_asegurar_dominio("acos", x, -1, 1))),
            "atan": lambda x: d(math.atan(x)),
            "atan2": lambda y, x: d(math.atan2(y, x)),
            "acot": lambda x: d(math.pi / 2 - math.atan(x)),
        }


def _tan(radianes: float) -> float:
    valor = math.tan(radianes)
    if abs(valor) > 1e15:
        raise ErrorExpresion("La tangente no está definida en ese ángulo")
    return _redondear_ruido(valor)


def _dividir(a: float, b: float, nombre: str) -> float:
    if b == 0 or abs(b) < 1e-15:
        raise ErrorExpresion(f"{nombre} no está definida en ese ángulo")
    return a / b


def _redondear_ruido(valor: float) -> float:
    """Corrige el ruido de coma flotante: ``sin(180°)`` debe dar 0, no 1.2e-16."""
    if abs(valor) < 1e-14:
        return 0.0
    redondeado = round(valor, 12)
    return redondeado if abs(valor - redondeado) < 1e-13 else valor


#: Funciones disponibles en las expresiones (las trigonométricas se añaden según
#: el modo de ángulo activo).
FUNCIONES: dict = {
    "sqrt": _raiz,
    "raiz": _raiz_n,
    "cbrt": lambda x: math.copysign(abs(x) ** (1 / 3), x),
    "exp": math.exp,
    "ln": _log,
    "log": lambda x, base=10: _log(x, base),
    "log10": lambda x: _log(x, 10),
    "log2": lambda x: _log(x, 2),
    "abs": abs,
    "sign": lambda x: (x > 0) - (x < 0),
    "floor": math.floor,
    "ceil": math.ceil,
    "trunc": math.trunc,
    "round": lambda x, n=0: round(x, int(n)),
    "factorial": _factorial,
    "gamma": math.gamma,
    "mod": lambda a, b: _modulo(a, b),
    "hypot": math.hypot,
    "gcd": lambda *xs: math.gcd(*(int(x) for x in xs)),
    "lcm": lambda *xs: math.lcm(*(int(x) for x in xs)),
    "min": min,
    "max": max,
    "sinh": math.sinh,
    "cosh": math.cosh,
    "tanh": math.tanh,
    "asinh": math.asinh,
    "acosh": lambda x: math.acosh(x) if x >= 1 else _fuera("acosh requiere x ≥ 1"),
    "atanh": lambda x: math.atanh(x) if -1 < x < 1 else _fuera("atanh requiere -1 < x < 1"),
    "degrees": math.degrees,
    "radians": math.radians,
    "grados": math.degrees,
    "radianes": math.radians,
}

#: Constantes disponibles en las expresiones.
CONSTANTES: dict = {
    "pi": math.pi,
    "e": math.e,
    "tau": math.tau,
    "phi": (1 + math.sqrt(5)) / 2,
    "inf": math.inf,
}


def _fuera(mensaje: str):
    raise ErrorExpresion(mensaje)


def _modulo(a, b):
    if b == 0:
        raise ErrorExpresion("No se puede calcular el módulo con divisor 0")
    return math.fmod(a, b)


# --------------------------------------------------------------------------- #
# Recorrido del árbol
# --------------------------------------------------------------------------- #

_OPERADORES_BINARIOS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}

_OPERADORES_UNARIOS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
}

# Cotas para evitar que una expresión bloquee la interfaz: 9**9**9 tardaría
# esencialmente para siempre y agotaría la memoria.
_MAX_EXPONENTE = 1e6
_MAX_BASE_ENTERA = 1e6


class _Evaluador(ast.NodeVisitor):
    def __init__(self, funciones: dict, variables: dict) -> None:
        self.funciones = funciones
        self.variables = variables

    # -- nodos permitidos -------------------------------------------------- #

    def visit_Expression(self, nodo: ast.Expression):
        return self.visit(nodo.body)

    def visit_Constant(self, nodo: ast.Constant):
        if isinstance(nodo.value, bool) or not isinstance(nodo.value, (int, float)):
            raise ErrorExpresion("Sólo se admiten valores numéricos")
        return nodo.value

    def visit_Name(self, nodo: ast.Name):
        nombre = nodo.id
        if nombre in self.variables:
            return self.variables[nombre]
        if nombre in CONSTANTES:
            return CONSTANTES[nombre]
        if nombre in self.funciones:
            raise ErrorExpresion(f"Falta el paréntesis en '{nombre}(...)'")
        raise ErrorExpresion(f"Nombre desconocido: '{nombre}'")

    def visit_BinOp(self, nodo: ast.BinOp):
        operacion = _OPERADORES_BINARIOS.get(type(nodo.op))
        if operacion is None:
            raise ErrorExpresion("Operador no permitido")

        izquierda = self.visit(nodo.left)
        derecha = self.visit(nodo.right)

        if isinstance(nodo.op, ast.Pow):
            return self._potencia(izquierda, derecha)

        if isinstance(nodo.op, (ast.Div, ast.FloorDiv, ast.Mod)) and derecha == 0:
            raise ErrorExpresion("No se puede dividir entre cero")

        try:
            return operacion(izquierda, derecha)
        except OverflowError:
            raise ErrorExpresion("El resultado es demasiado grande") from None
        except (TypeError, ValueError) as e:
            raise ErrorExpresion(f"Operación inválida: {e}") from e

    def visit_UnaryOp(self, nodo: ast.UnaryOp):
        operacion = _OPERADORES_UNARIOS.get(type(nodo.op))
        if operacion is None:
            raise ErrorExpresion("Operador unario no permitido")
        return operacion(self.visit(nodo.operand))

    def visit_Call(self, nodo: ast.Call):
        if not isinstance(nodo.func, ast.Name):
            raise ErrorExpresion("Sólo se pueden llamar funciones por su nombre")
        nombre = nodo.func.id
        funcion = self.funciones.get(nombre)
        if funcion is None:
            raise ErrorExpresion(f"Función desconocida: '{nombre}'")
        if nodo.keywords:
            raise ErrorExpresion("Los argumentos con nombre no están permitidos")

        argumentos = [self.visit(a) for a in nodo.args]
        try:
            return funcion(*argumentos)
        except ErrorExpresion:
            raise
        except TypeError:
            raise ErrorExpresion(f"Número de argumentos incorrecto en '{nombre}'") from None
        except (ValueError, ZeroDivisionError) as e:
            raise ErrorExpresion(f"'{nombre}' no está definida ahí ({e})") from e
        except OverflowError:
            raise ErrorExpresion(f"'{nombre}' produce un resultado demasiado grande") from None

    # -- cualquier otro nodo se rechaza ------------------------------------ #

    def generic_visit(self, nodo: ast.AST):
        raise ErrorExpresion("La expresión contiene elementos no permitidos")

    # -- auxiliares -------------------------------------------------------- #

    @staticmethod
    def _potencia(base, exponente):
        if abs(exponente) > _MAX_EXPONENTE:
            raise ErrorExpresion("Exponente demasiado grande")
        if (
            isinstance(base, int)
            and isinstance(exponente, int)
            and abs(base) > _MAX_BASE_ENTERA
            and exponente > 100
        ):
            raise ErrorExpresion("La potencia produce un número demasiado grande")
        if base < 0 and isinstance(exponente, float) and not float(exponente).is_integer():
            raise ErrorExpresion("Potencia fraccionaria de una base negativa (no real)")
        try:
            resultado = operator.pow(base, exponente)
        except OverflowError:
            raise ErrorExpresion("El resultado es demasiado grande") from None
        except ZeroDivisionError:
            raise ErrorExpresion("0 elevado a un exponente negativo no está definido") from None
        if isinstance(resultado, complex):
            raise ErrorExpresion("El resultado no es un número real")
        return resultado


def evaluar(
    expresion: str,
    modo_angulo: str = "RAD",
    variables: dict | None = None,
) -> float:
    """Evalúa ``expresion`` y devuelve el resultado numérico.

    Args:
        expresion: texto tal cual lo escribió el usuario.
        modo_angulo: ``"DEG"``, ``"RAD"`` o ``"GRAD"``.
        variables: valores extra disponibles, p. ej. ``{"ans": 42}``.

    Raises:
        ErrorExpresion: con un mensaje en castellano apto para mostrar al usuario.
    """
    texto = _preparar(expresion)

    funciones = dict(FUNCIONES)
    funciones.update(_Trig(modo_angulo).funciones())

    try:
        arbol = ast.parse(texto, mode="eval")
    except SyntaxError:
        raise ErrorExpresion("La expresión está mal escrita (revise los paréntesis y operadores)") from None
    except ValueError:
        raise ErrorExpresion("La expresión es demasiado compleja") from None

    resultado = _Evaluador(funciones, dict(variables or {})).visit(arbol)

    if isinstance(resultado, bool) or not isinstance(resultado, (int, float)):
        raise ErrorExpresion("La expresión no produce un número")
    if isinstance(resultado, float) and math.isnan(resultado):
        raise ErrorExpresion("El resultado no está definido")
    return resultado


def parentesis_pendientes(expresion: str) -> int:
    """Cuántos ``)`` faltan para equilibrar la expresión (útil para la interfaz)."""
    abiertos = 0
    for caracter in expresion:
        if caracter == "(":
            abiertos += 1
        elif caracter == ")":
            abiertos = max(0, abiertos - 1)
    return abiertos

axioma_nucleo/magnitudes.py:
"""Aritmética con unidades dentro de la calculadora.

Permite escribir ``5 km + 300 m`` y obtener ``5.3 km``, o ``5 km a millas`` para
convertir. Se apoya en el catálogo de :mod:`unidades`.

**Alcance deliberado.** Se admiten:

* sumas y restas entre magnitudes de la **misma** categoría (``5 km + 300 m``);
* producto y división por un número (``5 km * 3``, ``10 km / 4``);
* división entre magnitudes de la misma categoría, que da un número sin unidad
  (``10 km / 2 km`` → ``5``);
* conversión explícita con ``a``, ``en``, ``in``, ``to`` o ``→``.

**No** se admite crear unidades derivadas multiplicando o dividiendo magnitudes
de distinta categoría (``10 km / 2 h``): eso exigiría un motor de análisis
dimensional completo. En su lugar se devuelve un mensaje que lo explica y
remite al módulo de conversiones, donde ``km/h`` ya existe como unidad.
"""

from __future__ import annotations

import re
from dataclasses import dataclass

from . import unidades as uni
from .formato import formatear

__all__ = [
    "ErrorMagnitud",
    "Cantidad",
    "contiene_unidades",
    "evaluar",
    "SIMBOLOS",
]


class ErrorMagnitud(ValueError):
    """La expresión con unidades no es válida."""


#: Categorías que tienen sentido en la calculadora. Se dejan fuera «Cantidades y
#: prefijos» y «Proporción» porque sus símbolos de una letra (``m`` = mili,
#: ``a`` = atto) chocarían con los de longitud, y no son magnitudes que uno sume.
_CATEGORIAS_EXCLUIDAS = {"Cantidades y prefijos", "Proporción"}

#: Orden de preferencia cuando un símbolo existe en varias categorías.
_PRIORIDAD = [
    "Longitud", "Masa", "Tiempo", "Volumen", "Área", "Velocidad",
    "Temperatura", "Energía y trabajo", "Potencia", "Presión", "Fuerza",
    "Almacenamiento de datos", "Ángulo", "Frecuencia",
]

#: La temperatura usa escalas afines: sumar 20 °C + 5 °C no significa nada
#: (¿son 25 °C o 298 K + 278 K?). Se permite convertir, pero no operar.
_SOLO_CONVERSION = {"Temperatura"}


def _construir_indice() -> dict[str, list[tuple[str, uni.Unidad]]]:
    """Símbolo -> lista de (categoría, unidad), ordenada por preferencia."""
    indice: dict[str, list[tuple[str, uni.Unidad]]] = {}
    for nombre, categoria in uni.CATEGORIAS.items():
        if nombre in _CATEGORIAS_EXCLUIDAS:
            continue
        for unidad in categoria.unidades:
            # Los símbolos con espacios o paréntesis («gal US», «mes (30 d)») no
            # se pueden reconocer sin ambigüedad dentro de una expresión.
            if " " in unidad.simbolo or "(" in unidad.simbolo:
                continue
            indice.setdefault(unidad.simbolo, []).append((nombre, unidad))

    def clave(par: tuple[str, uni.Unidad]) -> tuple[int, str]:
        nombre = par[0]
        return (_PRIORIDAD.index(nombre) if nombre in _PRIORIDAD else len(_PRIORIDAD),
                nombre)

    for simbolo in indice:
        indice[simbolo].sort(key=clave)
    return indice


_INDICE = _construir_indice()

#: Símbolos reconocidos, del más largo al más corto (para casar «km/h» antes
#: que «km»).
SIMBOLOS = sorted(_INDICE, key=len, reverse=True)

#: Palabras que introducen una conversión explícita.
_CONVERSORES = ("→", "->", " a ", " en ", " in ", " to ")

_NUMERO = re.compile(r"\d+(?:\.\d+)?(?:[eE][+-]?\d+)?")


@dataclass(frozen=True)
class Cantidad:
    """Un número con su unidad, o sin ella si ``unidad`` es ``None``."""

    valor: float
    categoria: str | None = None
    unidad: uni.Unidad | None = None

    @property
    def es_numero(self) -> bool:
        return self.unidad is None

    def en_base(self) -> float:
        if self.unidad is None:
            return self.valor
        return self.unidad.a_base(self.valor)

    def convertida_a(self, otra: uni.Unidad) -> "Cantidad":
        if self.unidad is None:
            raise ErrorMagnitud("Ese valor no tiene unidad que convertir")
        return Cantidad(otra.desde_base(self.en_base()), self.categoria, otra)

    def texto(self, decimales: int = 6) -> str:
        if self.unidad is None:
            return formatear(self.valor, decimales)
        return f"{formatear(self.valor, decimales)} {self.unidad.simbolo}"


def contiene_unidades(expresion: str) -> bool:
    """True si la expresión parece llevar unidades (para no estorbar si no).

    La calculadora la usa para decidir si evalúa con este motor o con el
    evaluador normal, así que ante la duda debe decir que no.
    """
    cuerpo, destino = _separar_conversion(expresion)
    try:
        elementos = _tokenizar(cuerpo)
    except ErrorMagnitud:
        return False

    lleva_unidad = any(
        tipo == "cantidad" and isinstance(valor, Cantidad) and valor.unidad is not None
        for tipo, valor in elementos
    )
    if not lleva_unidad:
        return False
    # En una conversión, el destino también tiene que ser una unidad conocida.
    return destino is None or _casar_simbolo(destino, 0) == destino.strip()


# --------------------------------------------------------------------------- #
# Análisis léxico
# --------------------------------------------------------------------------- #


def _resolver_unidad(simbolo: str, pista: str | None) -> tuple[str, uni.Unidad]:
    """Elige la categoría de un símbolo, usando el resto de la expresión."""
    candidatos = _INDICE[simbolo]
    if pista:
        for nombre, unidad in candidatos:
            if nombre == pista:
                return nombre, unidad
    return candidatos[0]


def _tokenizar(expresion: str) -> list[tuple[str, object]]:
    """Convierte el texto en una lista de (tipo, valor).

    Los tipos son ``"cantidad"``, ``"op"`` y ``"paren"``. Una unidad sólo se
    reconoce **detrás de un número**: así ``sin(30)`` no confunde la ``s`` de
    segundo con el nombre de la función.
    """
    texto = expresion.strip().replace(",", ".")
    elementos: list[tuple[str, object]] = []
    i = 0
    n = len(texto)

    while i < n:
        caracter = texto[i]

        if caracter.isspace():
            i += 1
            continue

        if caracter in "+-*/×÷−":
            normalizado = {"×": "*", "÷": "/", "−": "-"}.get(caracter, caracter)
            elementos.append(("op", normalizado))
            i += 1
            continue

        if caracter in "()":
            elementos.append(("paren", caracter))
            i += 1
            continue

        coincidencia = _NUMERO.match(texto, i)
        if not coincidencia:
            raise ErrorMagnitud(
                f"No se entiende «{texto[i:].strip()[:20]}» en una expresión con unidades"
            )

        valor = float(coincidencia.group())
        i = coincidencia.end()

        # Unidad opcional pegada al número o separada por espacios.
        j = i
        while j < n and texto[j].isspace():
            j += 1
        simbolo = _casar_simbolo(texto, j)
        if simbolo is None:
            elementos.append(("cantidad", Cantidad(valor)))
        else:
            # La categoría se decide después, cuando se conoce toda la expresión.
            elementos.append(("cantidad", (valor, simbolo)))
            i = j + len(simbolo)

    return _asignar_categorias(elementos)


def _casar_simbolo(texto: str, posicion: int) -> str | None:
    """Símbolo de unidad más largo que empiece en ``posicion``, si lo hay."""
    for simbolo in SIMBOLOS:
        if not texto.startswith(simbolo, posicion):
            continue
        siguiente = posicion + len(simbolo)
        # Si detrás sigue una letra o un dígito, el símbolo era en realidad el
        # principio de otra palabra: «2sin(x)» no es «2 s» seguido de «in».
        if siguiente < len(texto) and (texto[siguiente].isalnum() or texto[siguiente] == "_"):
            continue
        return simbolo
    return None


def _asignar_categorias(crudos: list[tuple[str, object]]) -> list[tuple[str, object]]:
    """Decide la categoría de cada unidad usando las demás como contexto."""
    simbolos = [v[1] for t, v in crudos if t == "cantidad" and isinstance(v, tuple)]

    # Una categoría que sólo pueda venir de un símbolo no ambiguo sirve de pista
    # para los demás: en «5 km + 300 m», «km» fija Longitud y desambigua «m».
    pista: str | None = None
    for simbolo in simbolos:
        candidatos = _INDICE[simbolo]
        if len(candidatos) == 1:
            pista = candidatos[0][0]
            break

    resultado: list[tuple[str, object]] = []
    for tipo, valor in crudos:
        if tipo == "cantidad" and isinstance(valor, tuple):
            numero, simbolo = valor
            categoria, unidad = _resolver_unidad(simbolo, pista)
            resultado.append(("cantidad", Cantidad(numero, categoria, unidad)))
        else:
            resultado.append((tipo, valor))
    return resultado


# --------------------------------------------------------------------------- #
# Análisis sintáctico y evaluación
# --------------------------------------------------------------------------- #


class _Analizador:
    """Descenso recursivo sobre los elementos ya tokenizados."""

    def __init__(self, elementos: list[tuple[str, object]]) -> None:
        self.elementos = elementos
        self.posicion = 0

    def _mirar(self) -> tuple[str, object] | None:
        if self.posicion < len(self.elementos):
            return self.elementos[self.posicion]
        return None

    def analizar(self) -> Cantidad:
        resultado = self._suma()
        if self.posicion < len(self.elementos):
            raise ErrorMagnitud("La expresión con unidades está mal formada")
        return resultado

    def _suma(self) -> Cantidad:
        izquierda = self._producto()
        while True:
            actual = self._mirar()
            if actual is None or actual[0] != "op" or actual[1] not in "+-":
                return izquierda
            self.posicion += 1
            derecha = self._producto()
            izquierda = _sumar(izquierda, derecha, str(actual[1]))

    def _producto(self) -> Cantidad:
        izquierda = self._unario()
        while True:
            actual = self._mirar()
            if actual is None or actual[0] != "op" or actual[1] not in "*/":
                return izquierda
            self.posicion += 1
            derecha = self._unario()
            izquierda = _multiplicar(izquierda, derecha, str(actual[1]))

    def _unario(self) -> Cantidad:
        actual = self._mirar()
        if actual is not None and actual[0] == "op" and actual[1] in "+-":
            self.posicion += 1
            valor = self._unario()
            if actual[1] == "-":
                return Cantidad(-valor.valor, valor.categoria, valor.unidad)
            return valor
        return self._primario()

    def _primario(self) -> Cantidad:
        actual = self._mirar()
        if actual is None:
            raise ErrorMagnitud("Falta un valor en la expresión")

        if actual[0] == "paren" and actual[1] == "(":
            self.posicion += 1
            interior = self._suma()
            cierre = self._mirar()
            if cierre is None or cierre[0] != "paren" or cierre[1] != ")":
                raise ErrorMagnitud("Falta cerrar un paréntesis")
            self.posicion += 1
            return interior

        if actual[0] == "cantidad":
            self.posicion += 1
            return actual[1]  # type: ignore[return-value]

        raise ErrorMagnitud("La expresión con unidades está mal formada")


def _exigir_operable(cantidad: Cantidad, operacion: str) -> None:
    if cantidad.categoria in _SOLO_CONVERSION:
        raise ErrorMagnitud(
            f"No se pueden {operacion} temperaturas: las escalas °C y °F no "
            f"empiezan en el cero absoluto, así que la operación no significaría "
            f"nada. Sí puede convertirlas: «20 °C a °F»."
        )


def _sumar(a: Cantidad, b: Cantidad, signo: str) -> Cantidad:
    factor = 1.0 if signo == "+" else -1.0
    verbo = "sumar" if signo == "+" else "restar"

    if a.es_numero and b.es_numero:
        return Cantidad(a.valor + factor * b.valor)

    if a.es_numero or b.es_numero:
        con_unidad = b if a.es_numero else a
        raise ErrorMagnitud(
            f"No se puede {verbo} un número suelto y una magnitud "
            f"({con_unidad.unidad.simbolo}): falta la unidad en uno de los dos."
        )

    _exigir_operable(a, verbo)
    if a.categoria != b.categoria:
        raise ErrorMagnitud(
            f"No se puede {verbo} {a.categoria.lower()} y {b.categoria.lower()}: "
            f"«{a.unidad.simbolo}» y «{b.unidad.simbolo}» miden cosas distintas."
        )

    # El resultado se expresa en la unidad del primer operando, que es lo que
    # espera quien escribe «5 km + 300 m».
    en_unidad_de_a = a.unidad.desde_base(b.en_base())
    return Cantidad(a.valor + factor * en_unidad_de_a, a.categoria, a.unidad)


def _multiplicar(a: Cantidad, b: Cantidad, signo: str) -> Cantidad:
    if signo == "/" and b.valor == 0:
        raise ErrorMagnitud("No se puede dividir entre cero")

    if a.es_numero and b.es_numero:
        return Cantidad(a.valor * b.valor if signo == "*" else a.valor / b.valor)

    # Magnitud por (o entre) un número: la unidad se conserva.
    if b.es_numero:
        _exigir_operable(a, "multiplicar" if signo == "*" else "dividir")
        nuevo = a.valor * b.valor if signo == "*" else a.valor / b.valor
        return Cantidad(nuevo, a.categoria, a.unidad)

    if a.es_numero:
        if signo == "*":
            _exigir_operable(b, "multiplicar")
            return Cantidad(a.valor * b.valor, b.categoria, b.unidad)
        raise ErrorMagnitud(
            f"Dividir un número entre una magnitud daría una unidad inversa "
            f"(1/{b.unidad.simbolo}), que esta calculadora no maneja."
        )

    # Las dos llevan unidad.
    if signo == "/" and a.categoria == b.categoria:
        _exigir_operable(a, "dividir")
        if b.en_base() == 0:
            raise ErrorMagnitud("No se puede dividir entre cero")
        return Cantidad(a.en_base() / b.en_base())

    operacion = "multiplicar" if signo == "*" else "dividir"
    raise ErrorMagnitud(
        f"No se pueden {operacion} «{a.unidad.simbolo}» y «{b.unidad.simbolo}»: "
        f"haría falta una unidad derivada. Muchas ya existen en el módulo de "
        f"Conversiones (por ejemplo km/h o kWh)."
    )


# --------------------------------------------------------------------------- #
# API pública
# --------------------------------------------------------------------------- #


def _separar_conversion(expresion: str) -> tuple[str, str | None]:
    """Separa «expresión a unidad» en sus dos partes."""
    texto = expresion.strip()
    for conversor in _CONVERSORES:
        posicion = texto.rfind(conversor)
        if posicion <= 0:
            continue
        izquierda = texto[:posicion].strip()
        derecha = texto[posicion + len(conversor):].strip()
        if izquierda and derecha:
            return izquierda, derecha
    return texto, None


def evaluar(expresion: str, decimales: int = 6) -> Cantidad:
    """Evalúa una expresión con unidades y devuelve el resultado.

    >>> evaluar("5 km + 300 m").texto()
    '5.3 km'
    >>> evaluar("20 °C a °F").texto()
    '68 °F'
    """
    cuerpo, destino = _separar_conversion(expresion)

    elementos = _tokenizar(cuerpo)
    if not elementos:
        raise ErrorMagnitud("Introduzca una expresión")
    resultado = _Analizador(elementos).analizar()

    if destino is None:
        return resultado

    simbolo = _casar_simbolo(destino, 0)
    if simbolo is None or simbolo != destino.strip():
        raise ErrorMagnitud(f"No se reconoce la unidad de destino «{destino}»")
    if resultado.unidad is None:
        raise ErrorMagnitud("El resultado no tiene unidad, así que no hay nada que convertir")

    categoria, unidad = _resolver_unidad(simbolo, resultado.categoria)
    if categoria != resultado.categoria:
        raise ErrorMagnitud(
            f"No se puede convertir {resultado.categoria.lower()} a "
            f"{categoria.lower()}: «{resultado.unidad.simbolo}» y «{simbolo}» "
            f"miden cosas distintas."
        )
    return resultado.convertida_a(unidad)

axioma_nucleo/matrices.py:
"""Matrices y álgebra lineal.

Las matrices se escriben como texto plano, una fila por línea y los elementos
separados por espacios o comas. Se admiten fracciones y expresiones
(``1/2``, ``sqrt(2)``, ``pi``), así que los resultados pueden darse en forma
exacta además de decimal.
"""

from __future__ import annotations

import sympy as sp

from .simbolico import ErrorSimbolico, analizar, texto

__all__ = [
    "ErrorMatriz",
    "analizar_matriz",
    "matriz_a_texto",
    "propiedades",
    "operar",
    "resolver_sistema",
    "OPERACIONES_UNARIAS",
    "OPERACIONES_BINARIAS",
]

#: Cota de tamaño: más allá, las operaciones simbólicas tardan demasiado.
MAX_DIMENSION = 12


class ErrorMatriz(ValueError):
    """La matriz o la operación no son válidas."""


def analizar_matriz(texto_matriz: str, nombre: str = "la matriz") -> sp.Matrix:
    """Convierte texto en una matriz de sympy.

    >>> analizar_matriz("1 2\\n3 4")
    Matrix([[1, 2], [3, 4]])
    """
    lineas = [l.strip() for l in texto_matriz.strip().splitlines()]
    lineas = [l for l in lineas if l]
    if not lineas:
        raise ErrorMatriz(f"Escriba los valores de {nombre}")

    filas: list[list[sp.Expr]] = []
    for numero, linea in enumerate(lineas, 1):
        # Se admiten separadores por comas, punto y coma o espacios, y corchetes.
        limpia = linea.strip().lstrip("[").rstrip("],").replace(";", " ").replace(",", " ")
        celdas = limpia.split()
        if not celdas:
            continue
        try:
            filas.append([analizar(c) for c in celdas])
        except ErrorSimbolico as e:
            raise ErrorMatriz(f"Fila {numero} de {nombre}: {e}") from None

    if not filas:
        raise ErrorMatriz(f"Escriba los valores de {nombre}")

    anchos = {len(f) for f in filas}
    if len(anchos) > 1:
        raise ErrorMatriz(
            f"Todas las filas de {nombre} deben tener el mismo número de elementos "
            f"(se encontraron filas de {sorted(anchos)})"
        )
    if len(filas) > MAX_DIMENSION or len(filas[0]) > MAX_DIMENSION:
        raise ErrorMatriz(f"El tamaño máximo admitido es {MAX_DIMENSION}×{MAX_DIMENSION}")

    return sp.Matrix(filas)


def matriz_a_texto(matriz: sp.Matrix, decimales: int = 0) -> str:
    """Formatea una matriz alineando las columnas."""
    if matriz.rows == 0 or matriz.cols == 0:
        return "(matriz vacía)"

    def celda(valor) -> str:
        if decimales:
            try:
                return texto(sp.N(valor, decimales))
            except (TypeError, ValueError):
                return texto(valor)
        return texto(valor)

    tabla = [[celda(matriz[i, j]) for j in range(matriz.cols)] for i in range(matriz.rows)]
    anchos = [max(len(fila[j]) for fila in tabla) for j in range(matriz.cols)]
    return "\n".join(
        "[ " + "  ".join(v.rjust(anchos[j]) for j, v in enumerate(fila)) + " ]"
        for fila in tabla
    )


def _exigir_cuadrada(matriz: sp.Matrix, operacion: str) -> None:
    if matriz.rows != matriz.cols:
        raise ErrorMatriz(
            f"{operacion} sólo está definida para matrices cuadradas "
            f"(esta es {matriz.rows}×{matriz.cols})"
        )


def propiedades(matriz: sp.Matrix) -> list[tuple[str, str]]:
    """Ficha completa de una matriz."""
    filas: list[tuple[str, str]] = [
        ("Dimensión", f"{matriz.rows} × {matriz.cols}"),
        ("Rango", str(matriz.rank())),
    ]

    if matriz.rows == matriz.cols:
        determinante = sp.simplify(matriz.det())
        filas.append(("Determinante", texto(determinante)))
        filas.append(("Traza", texto(sp.simplify(matriz.trace()))))
        filas.append((
            "Invertible",
            "no (determinante nulo: matriz singular)" if determinante == 0 else "sí",
        ))

        if matriz.is_symmetric():
            filas.append(("Simétrica", "sí"))
        if matriz.is_diagonal():
            filas.append(("Diagonal", "sí"))
        if matriz == sp.eye(matriz.rows):
            filas.append(("Identidad", "sí"))
    else:
        filas.append((
            "Determinante",
            "no está definido para matrices no cuadradas",
        ))

    nulidad = matriz.cols - matriz.rank()
    filas.append(("Nulidad (dim. del núcleo)", str(nulidad)))
    return filas


# --------------------------------------------------------------------------- #
# Operaciones con una sola matriz
# --------------------------------------------------------------------------- #


def _op_transpuesta(m: sp.Matrix, _p) -> list[tuple[str, str]]:
    return [("Transpuesta", matriz_a_texto(m.T))]


def _op_determinante(m: sp.Matrix, _p) -> list[tuple[str, str]]:
    _exigir_cuadrada(m, "El determinante")
    valor = sp.simplify(m.det())
    filas = [("Determinante", texto(valor))]
    try:
        filas.append(("Valor aproximado", texto(sp.N(valor, 10))))
    except (TypeError, ValueError):
        pass
    if m.rows <= 3:
        filas.append(("Interpretación",
                      "área (2×2) o volumen (3×3) con signo del paralelepípedo "
                      "que forman los vectores fila"))
    return filas


def _op_inversa(m: sp.Matrix, _p) -> list[tuple[str, str]]:
    _exigir_cuadrada(m, "La inversa")
    if sp.simplify(m.det()) == 0:
        raise ErrorMatriz(
            "La matriz es singular (determinante nulo): no tiene inversa. "
            "Puede calcular en su lugar la pseudoinversa."
        )
    inversa = sp.simplify(m.inv())
    return [
        ("Inversa (exacta)", matriz_a_texto(inversa)),
        ("Inversa (decimal)", matriz_a_texto(inversa, decimales=6)),
        ("Comprobación A·A⁻¹", matriz_a_texto(sp.simplify(m * inversa))),
    ]


def _op_pseudoinversa(m: sp.Matrix, _p) -> list[tuple[str, str]]:
    return [("Pseudoinversa de Moore-Penrose", matriz_a_texto(sp.simplify(m.pinv()), 6))]


def _op_rref(m: sp.Matrix, _p) -> list[tuple[str, str]]:
    reducida, pivotes = m.rref()
    return [
        ("Forma escalonada reducida", matriz_a_texto(sp.simplify(reducida))),
        ("Columnas pivote", ", ".join(str(p + 1) for p in pivotes) or "ninguna"),
        ("Rango", str(len(pivotes))),
    ]


def _op_potencia(m: sp.Matrix, parametros) -> list[tuple[str, str]]:
    _exigir_cuadrada(m, "La potencia")
    exponente = int(parametros.get("exponente", 2))
    if not -20 <= exponente <= 20:
        raise ErrorMatriz("El exponente debe estar entre −20 y 20")
    if exponente < 0 and sp.simplify(m.det()) == 0:
        raise ErrorMatriz("No se puede elevar a un exponente negativo una matriz singular")
    return [(f"A^{exponente}", matriz_a_texto(sp.simplify(m ** exponente)))]


def _op_autovalores(m: sp.Matrix, _p) -> list[tuple[str, str]]:
    _exigir_cuadrada(m, "El cálculo de autovalores")
    filas: list[tuple[str, str]] = [
        ("Polinomio característico", texto(sp.factor(m.charpoly().as_expr()))),
    ]

    try:
        autovalores = m.eigenvals()
    except (NotImplementedError, sp.MatrixError) as e:
        raise ErrorMatriz(f"No se pudieron calcular los autovalores: {e}") from None

    for valor, multiplicidad in autovalores.items():
        simplificado = sp.simplify(valor)
        sufijo = f"  (multiplicidad {multiplicidad})" if multiplicidad > 1 else ""
        aproximado = ""
        try:
            numerico = sp.N(simplificado, 8)
            if texto(numerico) != texto(simplificado):
                aproximado = f"   ≈ {texto(numerico)}"
        except (TypeError, ValueError):
            pass
        filas.append(("Autovalor λ", f"{texto(simplificado)}{aproximado}{sufijo}"))

    try:
        for valor, multiplicidad, vectores in m.eigenvects():
            for vector in vectores:
                filas.append((
                    f"Autovector de λ = {texto(sp.simplify(valor))}",
                    matriz_a_texto(sp.simplify(vector.T)),
                ))
    except (NotImplementedError, sp.MatrixError):
        filas.append(("Autovectores", "no se pudieron calcular"))

    try:
        if m.is_diagonalizable():
            P, D = m.diagonalize()
            filas.append(("Diagonalizable", "sí,  A = P·D·P⁻¹"))
            filas.append(("P (autovectores en columnas)", matriz_a_texto(sp.simplify(P))))
            filas.append(("D (diagonal de autovalores)", matriz_a_texto(sp.simplify(D))))
        else:
            filas.append(("Diagonalizable", "no"))
    except (NotImplementedError, sp.MatrixError):
        pass

    return filas


def _op_nucleo(m: sp.Matrix, _p) -> list[tuple[str, str]]:
    base = m.nullspace()
    if not base:
        return [("Núcleo", "sólo el vector cero (la matriz tiene rango completo por columnas)")]
    filas = [("Dimensión del núcleo", str(len(base)))]
    for i, vector in enumerate(base, 1):
        filas.append((f"Vector {i} de la base", matriz_a_texto(sp.simplify(vector.T))))
    return filas


def _op_imagen(m: sp.Matrix, _p) -> list[tuple[str, str]]:
    base = m.columnspace()
    filas = [("Dimensión de la imagen (rango)", str(len(base)))]
    for i, vector in enumerate(base, 1):
        filas.append((f"Vector {i} de la base", matriz_a_texto(sp.simplify(vector.T))))
    return filas


def _op_lu(m: sp.Matrix, _p) -> list[tuple[str, str]]:
    _exigir_cuadrada(m, "La descomposición LU")
    try:
        L, U, permutaciones = m.LUdecomposition()
    except (NotImplementedError, sp.MatrixError) as e:
        raise ErrorMatriz(f"No se pudo descomponer: {e}") from None
    return [
        ("L (triangular inferior)", matriz_a_texto(sp.simplify(L))),
        ("U (triangular superior)", matriz_a_texto(sp.simplify(U))),
        ("Permutaciones de filas", str(permutaciones) if permutaciones else "ninguna"),
    ]


# --------------------------------------------------------------------------- #
# Operaciones con dos matrices
# --------------------------------------------------------------------------- #


def _op_sumar(a: sp.Matrix, b: sp.Matrix) -> list[tuple[str, str]]:
    if a.shape != b.shape:
        raise ErrorMatriz(
            f"Para sumar, las dos matrices deben tener la misma dimensión "
            f"(A es {a.rows}×{a.cols} y B es {b.rows}×{b.cols})"
        )
    return [("A + B", matriz_a_texto(sp.simplify(a + b)))]


def _op_restar(a: sp.Matrix, b: sp.Matrix) -> list[tuple[str, str]]:
    if a.shape != b.shape:
        raise ErrorMatriz(
            f"Para restar, las dos matrices deben tener la misma dimensión "
            f"(A es {a.rows}×{a.cols} y B es {b.rows}×{b.cols})"
        )
    return [("A − B", matriz_a_texto(sp.simplify(a - b)))]


def _op_multiplicar(a: sp.Matrix, b: sp.Matrix) -> list[tuple[str, str]]:
    if a.cols != b.rows:
        raise ErrorMatriz(
            f"Para multiplicar A·B, las columnas de A ({a.cols}) deben coincidir "
            f"con las filas de B ({b.rows})"
        )
    producto = sp.simplify(a * b)
    filas = [("A · B", matriz_a_texto(producto))]
    if b.cols == a.rows:
        filas.append(("B · A", matriz_a_texto(sp.simplify(b * a))))
        filas.append((
            "¿Conmutan?",
            "sí" if sp.simplify(a * b - b * a) == sp.zeros(a.rows, b.cols) else
            "no (el producto de matrices no es conmutativo)",
        ))
    return filas


def _op_producto_elemento(a: sp.Matrix, b: sp.Matrix) -> list[tuple[str, str]]:
    if a.shape != b.shape:
        raise ErrorMatriz("El producto elemento a elemento exige la misma dimensión")
    return [("A ∘ B (Hadamard)", matriz_a_texto(sp.simplify(a.multiply_elementwise(b))))]


def resolver_sistema(coeficientes: sp.Matrix, terminos: sp.Matrix) -> list[tuple[str, str]]:
    """Resuelve A·x = b y clasifica el sistema."""
    if coeficientes.rows != terminos.rows:
        raise ErrorMatriz(
            f"A tiene {coeficientes.rows} filas y b tiene {terminos.rows}: deben coincidir"
        )
    if terminos.cols != 1:
        terminos = terminos.reshape(terminos.rows * terminos.cols, 1)

    ampliada = coeficientes.row_join(terminos)
    rango = coeficientes.rank()
    rango_ampliada = ampliada.rank()
    incognitas = coeficientes.cols

    filas = [
        ("Matriz ampliada", matriz_a_texto(ampliada)),
        ("Rango de A", str(rango)),
        ("Rango de (A|b)", str(rango_ampliada)),
        ("Número de incógnitas", str(incognitas)),
    ]

    if rango < rango_ampliada:
        filas.append(("Clasificación", "SISTEMA INCOMPATIBLE: no tiene solución"))
        return filas

    simbolos = sp.symbols(f"x1:{incognitas + 1}")
    solucion = sp.linsolve((coeficientes, terminos), simbolos)
    if not solucion:
        filas.append(("Clasificación", "sin solución"))
        return filas

    tupla = next(iter(solucion))
    libres = sorted({str(s) for expresion in tupla for s in expresion.free_symbols})

    if rango == incognitas and not libres:
        filas.append(("Clasificación", "COMPATIBLE DETERMINADO: solución única"))
        for simbolo, valor in zip(simbolos, tupla):
            exacto = texto(sp.simplify(valor))
            aproximado = texto(sp.N(valor, 8))
            filas.append((
                str(simbolo),
                exacto if exacto == aproximado else f"{aproximado}   (exacto: {exacto})",
            ))
    else:
        grados = incognitas - rango
        filas.append((
            "Clasificación",
            f"COMPATIBLE INDETERMINADO: infinitas soluciones ({grados} "
            f"grado{'s' if grados != 1 else ''} de libertad)",
        ))
        for simbolo, valor in zip(simbolos, tupla):
            filas.append((str(simbolo), texto(sp.simplify(valor))))
        if libres:
            filas.append(("Parámetros libres", ", ".join(libres)))

    return filas


#: (clave, título, ¿necesita parámetro extra?)
OPERACIONES_UNARIAS = [
    ("propiedades", "Propiedades generales", None),
    ("transpuesta", "Transpuesta", None),
    ("determinante", "Determinante", None),
    ("inversa", "Inversa", None),
    ("pseudoinversa", "Pseudoinversa", None),
    ("rref", "Forma escalonada reducida (Gauss-Jordan)", None),
    ("potencia", "Potencia Aⁿ", "exponente"),
    ("autovalores", "Autovalores y autovectores", None),
    ("nucleo", "Núcleo (kernel)", None),
    ("imagen", "Imagen (espacio columna)", None),
    ("lu", "Descomposición LU", None),
]

OPERACIONES_BINARIAS = [
    ("sumar", "A + B"),
    ("restar", "A − B"),
    ("multiplicar", "A · B"),
    ("hadamard", "A ∘ B (elemento a elemento)"),
    ("sistema", "Resolver A·x = b"),
]

_UNARIAS = {
    "propiedades": lambda m, p: propiedades(m),
    "transpuesta": _op_transpuesta,
    "determinante": _op_determinante,
    "inversa": _op_inversa,
    "pseudoinversa": _op_pseudoinversa,
    "rref": _op_rref,
    "potencia": _op_potencia,
    "autovalores": _op_autovalores,
    "nucleo": _op_nucleo,
    "imagen": _op_imagen,
    "lu": _op_lu,
}

_BINARIAS = {
    "sumar": _op_sumar,
    "restar": _op_restar,
    "multiplicar": _op_multiplicar,
    "hadamard": _op_producto_elemento,
    "sistema": resolver_sistema,
}


def operar(clave: str, a: sp.Matrix, b: sp.Matrix | None = None,
           parametros: dict | None = None) -> list[tuple[str, str]]:
    """Aplica la operación indicada y devuelve las filas de resultado."""
    parametros = parametros or {}

    if clave in _UNARIAS:
        return _UNARIAS[clave](a, parametros)

    if clave in _BINARIAS:
        if b is None:
            raise ErrorMatriz("Esta operación necesita una segunda matriz")
        return _BINARIAS[clave](a, b)

    raise ErrorMatriz(f"Operación desconocida: {clave!r}")

axioma_nucleo/simbolico.py:
"""Base común para todo lo que trabaja con expresiones simbólicas (sympy).

Los módulos de ecuaciones, sistemas, cálculo y el graficador compartían la misma
configuración del analizador y las mismas comprobaciones. Aquí están una sola
vez, con dos objetivos:

* aceptar la notación que la gente escribe de verdad (``2x^2`` en vez de
  ``2*x**2``);
* no dejar que ``parse_expr`` reciba texto sin filtrar. sympy evalúa el código
  que se le pasa, así que se rechazan de antemano los nombres que no son
  matemáticos (``__import__``, ``open``, atributos con punto…).
"""

from __future__ import annotations

import re

import sympy as sp
from sympy.parsing.sympy_parser import (
    convert_xor, implicit_multiplication_application, parse_expr,
    standard_transformations,
)

__all__ = [
    "ErrorSimbolico",
    "TRANSFORMACIONES",
    "analizar",
    "analizar_igualdad",
    "incognitas",
    "a_funcion",
    "texto",
    "aproximar",
    "FUNCIONES_CONOCIDAS",
]

TRANSFORMACIONES = standard_transformations + (
    implicit_multiplication_application,  # 2x  ->  2*x
    convert_xor,                          # x^2 ->  x**2
)


class ErrorSimbolico(ValueError):
    """La expresión no se puede interpretar."""


#: Funciones que se aceptan dentro de una expresión.
FUNCIONES_CONOCIDAS = frozenset({
    "sin", "cos", "tan", "cot", "sec", "csc",
    "asin", "acos", "atan", "acot", "asec", "acsc", "atan2",
    "sinh", "cosh", "tanh", "coth", "asinh", "acosh", "atanh",
    "exp", "log", "ln", "sqrt", "cbrt", "root", "Abs", "abs", "sign",
    "floor", "ceiling", "ceil", "factorial", "gamma", "binomial",
    "Max", "Min", "max", "min", "re", "im", "arg", "conjugate",
    "Sum", "Product", "Piecewise", "Heaviside", "erf",
})

#: Nombres reservados que sympy entiende como constantes.
CONSTANTES_CONOCIDAS = frozenset({"pi", "E", "e", "I", "oo", "zoo", "nan", "phi", "tau"})

# Cualquier cosa que parezca acceso a atributos, subrayados dobles o llamadas a
# funciones que no estén en la lista blanca se rechaza antes de llegar a sympy.
_PROHIBIDO = re.compile(r"__|\bimport\b|\bopen\b|\beval\b|\bexec\b|\blambda\b|;|\bclass\b|\bdef\b")
_ATRIBUTO = re.compile(r"[A-Za-z_]\w*\s*\.\s*[A-Za-z_]")
_LLAMADA = re.compile(r"([A-Za-z_]\w*)\s*\(")

_LONGITUD_MAXIMA = 500


def _validar_texto(expresion: str, funciones_extra: frozenset | None = None) -> str:
    limpio = expresion.strip()
    if not limpio:
        raise ErrorSimbolico("Introduzca una expresión")
    if len(limpio) > _LONGITUD_MAXIMA:
        raise ErrorSimbolico(
            f"La expresión es demasiado larga (máximo {_LONGITUD_MAXIMA} caracteres)"
        )
    if _PROHIBIDO.search(limpio) or _ATRIBUTO.search(limpio):
        raise ErrorSimbolico("La expresión contiene elementos no permitidos")

    permitidas = FUNCIONES_CONOCIDAS | (funciones_extra or frozenset())
    for nombre in _LLAMADA.findall(limpio):
        if nombre not in permitidas:
            raise ErrorSimbolico(
                f"Función desconocida: «{nombre}». "
                f"Consulte el manual para ver las funciones disponibles."
            )
    return limpio


def analizar(expresion: str, funciones_extra: frozenset | None = None,
             locales: dict | None = None) -> sp.Expr:
    """Convierte texto en una expresión de sympy.

    Args:
        expresion: texto tal cual lo escribió el usuario.
        funciones_extra: nombres adicionales que se aceptan además de la lista
            blanca. Lo usan los módulos que necesitan construcciones propias,
            como ``Derivative`` y ``y(x)`` en las ecuaciones diferenciales. La
            lista base se mantiene estrecha a propósito.
        locales: símbolos ya construidos que el analizador debe reconocer. Es
            imprescindible al declarar funciones: sin decirle que ``y`` es una
            función, la multiplicación implícita interpreta ``y(x)`` como
            ``y·x``.

    >>> analizar("2x^2 - 4")
    2*x**2 - 4
    """
    limpio = _validar_texto(expresion, funciones_extra)
    # Las variables del usuario entran como símbolos propios. Sin esto, la
    # multiplicación implícita parte «volumen» en v·o·l·u·m·e·n y el resultado
    # de un apartado deja de poder usarse en otro.
    conocidas = {nombre: sp.Symbol(nombre) for nombre in _variables_definidas()}
    conocidas.update(locales or {})
    try:
        resultado = parse_expr(limpio, transformations=TRANSFORMACIONES,
                               local_dict=conocidas or None, evaluate=True)
    except (SyntaxError, TypeError, ValueError, AttributeError, RecursionError) as e:
        raise ErrorSimbolico(f"No se entiende la expresión: {e}") from e

    if not isinstance(resultado, sp.Basic):
        raise ErrorSimbolico("La expresión no es matemática")
    return resultado


def _variables_definidas() -> dict[str, float]:
    """Variables que el usuario ha definido, si el módulo está disponible."""
    from .variables import valores

    return valores()


def sustituir_variables(*expresiones: sp.Expr) -> tuple[sp.Expr, ...]:
    """Cambia las variables del usuario por su valor en estas expresiones.

    Es lo que permite escribir ``x^2 = volumen`` después de haber guardado el
    volumen desde Geometría.

    Si sustituirlo todo dejara la expresión **sin ninguna incógnita**, no se
    sustituye nada: significa que el nombre en cuestión es lo que se busca
    (alguien definió ``x`` y ahora quiere resolver en ``x``), y convertirlo en
    número dejaría una ecuación sin sentido.
    """
    definidas = _variables_definidas()
    if not definidas:
        return expresiones

    cambios = {sp.Symbol(nombre): sp.Float(valor) for nombre, valor in definidas.items()}
    cambiadas = tuple(e.subs(cambios) for e in expresiones)

    antes = set().union(*(e.free_symbols for e in expresiones)) if expresiones else set()
    despues = set().union(*(e.free_symbols for e in cambiadas)) if cambiadas else set()
    if antes and not despues:
        return expresiones
    return cambiadas


def analizar_igualdad(texto_ecuacion: str, *, igualar_a_cero: bool = True) -> tuple[sp.Expr, sp.Expr]:
    """Separa «izquierda = derecha». Si no hay «=», se supone «= 0»."""
    limpio = texto_ecuacion.strip()
    if limpio.count("=") > 1:
        raise ErrorSimbolico("La expresión sólo puede tener un signo «=»")

    izquierda, signo, derecha = limpio.partition("=")
    if not signo:
        derecha = "0" if igualar_a_cero else ""
    if not derecha.strip():
        derecha = "0"
    return sustituir_variables(analizar(izquierda), analizar(derecha))


def incognitas(*expresiones: sp.Expr) -> list[sp.Symbol]:
    """Símbolos libres de las expresiones, ordenados por nombre.

    Se ordenan poniendo primero las letras habituales (x, y, z, t) para que la
    variable «natural» de una función quede la primera.
    """
    simbolos: set[sp.Symbol] = set()
    for expresion in expresiones:
        simbolos |= expresion.free_symbols

    preferidas = ["x", "y", "z", "t", "u", "v", "w", "n", "k"]

    def clave(simbolo: sp.Symbol) -> tuple[int, str]:
        nombre = simbolo.name
        return (preferidas.index(nombre) if nombre in preferidas else len(preferidas), nombre)

    return sorted(simbolos, key=clave)


def variable_principal(expresion: sp.Expr, preferida: str = "") -> sp.Symbol:
    """La variable respecto a la que tiene sentido derivar, integrar o graficar."""
    libres = incognitas(expresion)
    if preferida:
        for simbolo in libres:
            if simbolo.name == preferida:
                return simbolo
        return sp.Symbol(preferida)
    if not libres:
        return sp.Symbol("x")
    return libres[0]


def a_funcion(expresion: sp.Expr, variable: sp.Symbol):
    """Compila la expresión a una función de numpy para poder representarla."""
    try:
        return sp.lambdify(variable, expresion, ["numpy"])
    except Exception as e:  # sympy lanza tipos muy variados
        raise ErrorSimbolico(f"Esta expresión no se puede representar: {e}") from e


def texto(expresion) -> str:
    """Representación legible de una expresión."""
    try:
        return sp.sstr(expresion)
    except Exception:
        return str(expresion)


def aproximar(valor, decimales: int = 6) -> str:
    """Valor numérico de una expresión, o su forma simbólica si no es numérica."""
    try:
        numero = sp.N(valor, max(2, decimales))
    except (TypeError, ValueError):
        return texto(valor)
    return texto(numero)


def es_real(valor) -> bool:
    """True si el valor es un número real (o casi, salvo ruido numérico)."""
    try:
        complejo = complex(sp.N(valor))
    except (TypeError, ValueError):
        return bool(getattr(valor, "is_real", False))
    return abs(complejo.imag) < 1e-12

axioma_nucleo/variables.py:
"""Variables que define el usuario, compartidas por toda la aplicación.

Si en la calculadora se escribe ``r = 2.5``, ese valor debe servir también en los
campos de Geometría o dentro de una ecuación. Por eso viven aquí y no dentro de
un panel concreto.

No se guardan en disco a propósito: son el borrador de un problema, no una
preferencia. Al cerrar la aplicación desaparecen, igual que la memoria de una
calculadora de bolsillo.
"""

from __future__ import annotations

__all__ = [
    "ErrorVariable",
    "definir",
    "borrar",
    "borrar_todas",
    "valores",
    "resumen",
    "nombre_disponible",
]


class ErrorVariable(ValueError):
    """El nombre de la variable no se puede usar."""


#: Nombre -> valor. Deliberadamente global: es el espacio de trabajo del usuario.
_valores: dict[str, float] = {}

#: Tope para que la barra de variables no crezca sin control.
MAX_VARIABLES = 40


def _reservados() -> set[str]:
    """Nombres que ya significan algo y no se pueden reutilizar."""
    from .evaluador import CONSTANTES, FUNCIONES

    return set(CONSTANTES) | set(FUNCIONES) | {"ans", "mem"}


def nombre_disponible(nombre: str) -> bool:
    return bool(nombre) and nombre.isidentifier() and nombre not in _reservados()


def definir(nombre: str, valor: float) -> None:
    """Guarda una variable. Lanza ``ErrorVariable`` si el nombre no vale."""
    if not nombre or not nombre.isidentifier():
        raise ErrorVariable(f"«{nombre}» no es un nombre válido para una variable")
    if nombre in _reservados():
        raise ErrorVariable(
            f"«{nombre}» es un nombre reservado (una constante o una función): "
            f"elija otro."
        )
    if nombre not in _valores and len(_valores) >= MAX_VARIABLES:
        raise ErrorVariable(
            f"Ya hay {MAX_VARIABLES} variables definidas. Borre alguna antes de "
            f"añadir más."
        )
    _valores[nombre] = float(valor)


def borrar(nombre: str) -> None:
    _valores.pop(nombre, None)


def borrar_todas() -> None:
    _valores.clear()


def valores() -> dict[str, float]:
    """Copia de las variables, para pasarla al evaluador."""
    return dict(_valores)


def resumen(decimales: int = 6) -> str:
    """Texto de una línea con las variables definidas, para la interfaz."""
    if not _valores:
        return ""
    from .formato import formatear

    return "   ".join(f"{n} = {formatear(v, decimales)}" for n, v in _valores.items())

puente.py:
"""Puente entre el núcleo de Axioma y la interfaz web.

Se ejecuta dentro del navegador, sobre Pyodide, e importa **el mismo**
``src/core`` que usa la aplicación de escritorio. Todo lo que devuelve es JSON,
que es lo único que cruza limpiamente hacia JavaScript.

Regla de la casa: aquí no se calcula nada. Si algo hay que resolver, lo resuelve
el núcleo; este archivo sólo traduce entradas y da formato a las salidas.
"""

from __future__ import annotations

import json
import math
import traceback

from axioma_nucleo import bases
from axioma_nucleo import figuras as geo
from axioma_nucleo import magnitudes
from axioma_nucleo import unidades as uni
from axioma_nucleo import variables
from axioma_nucleo.evaluador import ErrorExpresion, evaluar
from axioma_nucleo.formato import formatear


def _responder(funcion, *args, **kwargs) -> str:
    """Ejecuta algo del núcleo y devuelve siempre JSON, error incluido.

    Una excepción que cruce hacia JavaScript se convierte en un mensaje
    ilegible; así el navegador siempre recibe la misma forma de respuesta.
    """
    try:
        return json.dumps({"ok": True, "datos": funcion(*args, **kwargs)},
                          ensure_ascii=False, default=str)
    except Exception as e:                                     # noqa: BLE001
        return json.dumps({
            "ok": False,
            "error": str(e) or type(e).__name__,
            "tipo": type(e).__name__,
            "detalle": traceback.format_exc(limit=3),
        }, ensure_ascii=False)


# --------------------------------------------------------------- calculadora -- #

def _entorno() -> dict:
    return dict(variables.valores())


def _calcular(expresion: str, modo: str = "DEG", decimales: int = 6) -> dict:
    expresion = (expresion or "").strip()
    if not expresion:
        raise ValueError("No hay nada que calcular")

    asignacion = None
    if expresion.count("=") == 1:
        izquierda, _, derecha = expresion.partition("=")
        nombre = izquierda.strip()
        if nombre.isidentifier() and derecha.strip():
            asignacion, expresion = nombre, derecha.strip()

    if magnitudes.contiene_unidades(expresion):
        cantidad = magnitudes.evaluar(expresion)
        if asignacion and cantidad.unidad is not None:
            raise ValueError(
                f"Las variables guardan números sin unidad. Convierta antes: "
                f"«{asignacion} = {expresion} a {cantidad.unidad.simbolo}»."
            )
        valor, texto = cantidad.valor, cantidad.texto(decimales)
    else:
        valor = evaluar(expresion, modo, _entorno())
        texto = formatear(valor, decimales)

    if asignacion:
        variables.definir(asignacion, valor)
    return {"texto": texto, "valor": valor, "variable": asignacion,
            "variables": _entorno()}


def calcular(expresion: str, modo: str = "DEG", decimales: int = 6) -> str:
    return _responder(_calcular, expresion, modo, decimales)


def vista_previa(expresion: str, modo: str = "DEG", decimales: int = 6) -> str:
    """Como calcular, pero sin definir variables ni protestar si va a medias."""
    def hacer() -> dict:
        texto = (expresion or "").strip()
        if not texto or "=" in texto:
            return {"texto": ""}
        try:
            if magnitudes.contiene_unidades(texto):
                return {"texto": magnitudes.evaluar(texto).texto(decimales)}
            return {"texto": formatear(evaluar(texto, modo, _entorno()), decimales)}
        except (ErrorExpresion, magnitudes.ErrorMagnitud, ValueError, ArithmeticError):
            return {"texto": ""}

    return _responder(hacer)


# ----------------------------------------------------------------- variables -- #

def listar_variables() -> str:
    return _responder(lambda: _entorno())


def borrar_variables() -> str:
    def hacer() -> dict:
        variables.borrar_todas()
        return {}

    return _responder(hacer)


def definir_variable(nombre: str, valor: float) -> str:
    def hacer() -> dict:
        variables.definir(nombre, float(valor))
        return {"variables": _entorno()}

    return _responder(hacer)


# --------------------------------------------------------------- conversiones -- #

def categorias() -> str:
    def hacer() -> list:
        return [{"grupo": grupo, "nombres": list(nombres)}
                for grupo, nombres in uni.GRUPOS.items()]

    return _responder(hacer)


def unidades_de(categoria: str) -> str:
    def hacer() -> dict:
        cat = uni.categoria(categoria)
        return {
            "predeterminada": cat.predeterminada,
            "nota": cat.nota,
            "unidades": [{"simbolo": u.simbolo, "etiqueta": u.etiqueta,
                          "nombre": u.nombre}
                         for u in cat.unidades],
        }

    return _responder(hacer)


def convertir(valor: float, origen: str, destino: str, categoria: str,
              decimales: int = 6) -> str:
    def hacer() -> dict:
        resultado = uni.convertir(float(valor), origen, destino, categoria)
        tabla = [
            {"etiqueta": unidad.etiqueta, "valor": v, "texto": formatear(v, decimales)}
            for unidad, v in uni.tabla_completa(float(valor), origen, categoria)
        ]
        return {"valor": resultado, "texto": formatear(resultado, decimales),
                "tabla": tabla}

    return _responder(hacer)


# ------------------------------------------------------------------ geometría -- #

def lista_figuras() -> str:
    def hacer() -> list:
        return [{"nombre": nombre, "grupo": figura.grupo}
                for nombre, figura in geo.FIGURAS.items()]

    return _responder(hacer)


def parametros_de(figura: str) -> str:
    def hacer() -> dict:
        f = geo.figura(figura)
        return {
            "nombre": f.nombre,
            "nota": f.nota,
            "formulas": list(f.formulas),
            "parametros": [
                {"simbolo": p.simbolo, "etiqueta": p.etiqueta, "unidad": p.unidad,
                 "entero": p.entero, "predeterminado": p.predeterminado,
                 "ayuda": p.ayuda}
                for p in f.parametros
            ],
        }

    return _responder(hacer)


def calcular_figura(figura: str, valores_json: str, decimales: int = 6) -> str:
    def hacer() -> dict:
        f = geo.figura(figura)
        crudos = json.loads(valores_json)

        # Cada dato puede venir como «5 cm», «sqrt(16)» o «radio»: se resuelve
        # igual que en el escritorio, y las longitudes se unifican a la primera
        # unidad que aparezca.
        longitudes = [p.simbolo for p in f.parametros if p.unidad in ("u", "u²", "u³")]
        cantidades: dict[str, magnitudes.Cantidad] = {}
        for simbolo, texto in crudos.items():
            cantidades[simbolo] = _cantidad(str(texto))

        referencia = None
        for simbolo in longitudes:
            cantidad = cantidades.get(simbolo)
            if cantidad is not None and cantidad.unidad is not None:
                if cantidad.categoria != "Longitud":
                    raise ValueError(
                        f"«{cantidad.unidad.simbolo}» no es una unidad de longitud."
                    )
                referencia = cantidad.unidad
                break

        valores = {}
        for simbolo, cantidad in cantidades.items():
            if referencia is not None and simbolo in longitudes and cantidad.unidad:
                cantidad = cantidad.convertida_a(referencia)
            valores[simbolo] = cantidad.valor

        def con_unidad(sufijo: str) -> str:
            if referencia is None or sufijo not in ("u", "u²", "u³"):
                return sufijo
            return referencia.simbolo + sufijo[1:]

        resultados = f.calcular(valores)
        return {
            "formulas": list(f.formulas),
            "resultados": [
                {"etiqueta": r.etiqueta, "valor": r.valor,
                 "texto": formatear(r.valor, decimales, unidad=con_unidad(r.unidad))}
                for r in resultados
            ],
        }

    return _responder(hacer)


def _cantidad(texto: str) -> magnitudes.Cantidad:
    """Lee un dato del usuario: número, expresión, variable o magnitud."""
    texto = texto.strip()
    if not texto:
        raise ValueError("Faltan datos por rellenar")
    try:
        return magnitudes.Cantidad(float(texto.replace(",", ".")), None)
    except ValueError:
        pass
    if magnitudes.contiene_unidades(texto):
        return magnitudes.evaluar(texto)
    return magnitudes.Cantidad(float(evaluar(texto, "DEG", _entorno())), None)


# ------------------------------------------------------------------ ecuaciones -- #

def resolver_ecuacion(texto: str, decimales: int = 6) -> str:
    def hacer() -> dict:
        # sympy se importa aquí y no arriba: pesa unos segundos de descarga y
        # la calculadora, las conversiones y la geometría no lo necesitan. Así
        # la aplicación abre al momento y sólo paga quien resuelve ecuaciones.
        from axioma_nucleo import simbolico as sim

        izquierda, derecha = sim.analizar_igualdad(texto)
        libres = sim.incognitas(izquierda, derecha)
        if not libres:
            raise ValueError("La expresión no contiene ninguna incógnita")
        if len(libres) > 1:
            nombres = ", ".join(s.name for s in libres)
            raise ValueError(f"Hay varias incógnitas ({nombres}): despeje una sola")

        incognita = libres[0]
        expresion = sim.sp.simplify(izquierda - derecha)
        soluciones = sim.sp.solve(sim.sp.Eq(expresion, 0), incognita, dict=False)
        if not isinstance(soluciones, list):
            soluciones = [soluciones]

        salida = []
        for solucion in soluciones:
            try:
                aproximado = complex(sim.sp.N(solucion))
            except (TypeError, ValueError):
                salida.append({"exacto": str(solucion), "aproximado": None})
                continue
            if abs(aproximado.imag) < 1e-12:
                texto_aprox = formatear(aproximado.real, decimales)
                valor = aproximado.real
            else:
                texto_aprox = f"{aproximado.real:.{decimales}g} + {aproximado.imag:.{decimales}g}i"
                valor = None
            salida.append({"exacto": str(solucion), "aproximado": texto_aprox,
                           "valor": valor})

        return {"incognita": incognita.name,
                "normalizada": f"{sim.sp.expand(expresion)} = 0",
                "factorizada": str(sim.sp.factor(expresion)),
                "soluciones": salida}

    return _responder(hacer)


# --------------------------------------------------------------------- bases -- #

def convertir_base(texto: str, origen: int, decimales: int = 8) -> str:
    def hacer() -> dict:
        return {
            "valor": bases.a_decimal(texto, int(origen)),
            "tabla": [{"base": base, "nombre": bases.nombre_base(base), "texto": salida}
                      for base, salida in bases.tabla_bases(texto, int(origen), decimales)],
        }

    return _responder(hacer)


# ------------------------------------------------------------- combinatoria -- #

def combinatoria(operacion: str, n: float, r: float = 0) -> str:
    def hacer() -> dict:
        n_entero, r_entero = int(n), int(r)
        tabla = {
            "factorial": lambda: math.factorial(n_entero),
            "combinaciones": lambda: math.comb(n_entero, r_entero),
            "permutaciones": lambda: math.perm(n_entero, r_entero),
            "variaciones_rep": lambda: n_entero ** r_entero,
            "combinaciones_rep": lambda: math.comb(n_entero + r_entero - 1, r_entero),
        }
        if operacion not in tabla:
            raise ValueError(f"Operación desconocida: {operacion}")
        return {"valor": str(tabla[operacion]())}

    return _responder(hacer)


# --------------------------------------------------------------------- cálculo -- #

def calculo(operacion: str, expresion: str, variable: str = "x",
            desde: str = "", hasta: str = "") -> str:
    """Derivadas, integrales y límites. Devuelve pares (etiqueta, valor)."""
    def hacer() -> dict:
        from axioma_nucleo import calculo as calc

        if operacion == "derivada":
            filas = calc.derivar(expresion, variable)
        elif operacion == "integral":
            filas = calc.integrar(expresion, variable)
        elif operacion == "integral_definida":
            filas = calc.integrar_definida(expresion, variable, desde, hasta)
        elif operacion == "limite":
            filas = calc.limite(expresion, variable, desde or "0")
        elif operacion == "analisis":
            filas = calc.analizar_funcion(expresion, variable)
        else:
            raise ValueError(f"Operación desconocida: {operacion}")
        return {"filas": [{"etiqueta": e, "valor": v} for e, v in filas]}

    return _responder(hacer)
